    'Invalid User ID or password. Please try again.' => 'පරිශීලක අංකය හෝ මුරපදය වැරදියි. නැවත උත්සාහ කරන්න.',
    'Invalid credentials. Please try again.' => 'ඇතුළු වීමේ විස්තර වැරදියි. නැවත උත්සාහ කරන්න.',
    'Too many login attempts. Please try again in {n} minutes.' => 'ඇතුළු වීමට කළ උත්සාහ වැඩියි. මිනිත්තු {n}කින් නැවත උත්සාහ කරන්න.',
    'Your account has been deactivated. Please contact the administration for assistance.' => 'ඔබේ ගිණුම අක්‍රිය කර ඇත. සහාය සඳහා කාර්යාලය අමතන්න.',
    'Your student account has been deactivated. Please contact the administration for assistance.' => 'ඔබේ සිසු ගිණුම අක්‍රිය කර ඇත. සහාය සඳහා කාර්යාලය අමතන්න.',
    'Your parent account has been deactivated. Please contact the administration for assistance.' => 'ඔබේ දෙමාපිය ගිණුම අක්‍රිය කර ඇත. සහාය සඳහා කාර්යාලය අමතන්න.',
    'You have been logged out successfully.' => 'ඔබ සාර්ථකව ඉවත් විය.',
    'Password changed successfully.' => 'මුරපදය සාර්ථකව වෙනස් කළා.',
    'Current password is incorrect.' => 'දැනට ඇති මුරපදය වැරදියි.',
    'Failed to update password. Please try again.' => 'මුරපදය යාවත්කාලීන කිරීම අසාර්ථක විය. නැවත උත්සාහ කරන්න.',
    'Password must contain at least one uppercase letter, one lowercase letter, one digit, and one special character.' => 'මුරපදයේ අවම වශයෙන් එක් කැපිටල් අකුරක්, එක් සිම්පල් අකුරක්, එක් ඉලක්කමක් සහ එක් විශේෂ සංකේතයක් තිබිය යුතුයි.',
    'That page had been open for a while, so it has been refreshed. Please try again.' => 'මෙම පිටුව බොහෝ වේලාවක් විවෘතව තිබූ නිසා අලුත් කළා. කරුණාකර නැවත උත්සාහ කරන්න.',

