    'Your {month} fee is overdue. Settle it to reopen this class.' => 'ඔබේ {month} ගාස්තුව කල් ඉකුත් වී ඇත. මෙම පන්තිය නැවත විවෘත කිරීමට එය ගෙවන්න.',
