    'Once the office records your payment this class opens again, with everything posted for the month.' => 'කාර්යාලය ඔබේ ගෙවීම සටහන් කළ පසු, මාසය සඳහා එකතු කළ සියල්ල සමඟ මෙම පන්තිය නැවත විවෘත වේ.',
    '{n} questions' => 'ප්‍රශ්න {n}',
