    'Rs. {n} a month' => 'මසකට රු. {n}',
    'No quizzes sat yet.' => 'තවම ප්‍රශ්නාවලි කර නැත.',
    'Recent attendance' => 'මෑත පැමිණීම',
    'Nothing recorded yet.' => 'තවම කිසිවක් සටහන් කර නැත.',
    'Overview' => 'දළ විශ්ලේෂණය',
    'Being marked' => 'ලකුණු දමමින්',
    'Total outstanding' => 'මුළු ගෙවිය යුතු මුදල',
    'Nothing owing' => 'ගෙවිය යුතු කිසිවක් නැත',
    'Class material and quizzes stay locked for any month that is not settled.' => 'ගාස්තුව නොගෙවූ ඕනෑම මාසයක පාඩම් ද්‍රව්‍ය සහ ප්‍රශ්නාවලි අගුළු දමා ඇත.',
    'Every month' => 'සෑම මාසයක්ම',
    'No fees raised yet.' => 'තවම ගාස්තු නිකුත් කර නැත.',
    'Due' => 'ගෙවිය යුතු',
    '{n} class' => 'පන්ති {n}',
    '{n} classes' => 'පන්ති {n}',
    'No quizzes, attendance or material yet.' => 'තවම ප්‍රශ්නාවලි, පැමිණීම හෝ පාඩම් ද්‍රව්‍ය නැත.',
    'Excused' => 'සමාව දී ඇත',
    'Partial' => 'කොටසක් ගෙවා ඇත',
    'My child' => 'මගේ දරුවා',
    'My calendar' => 'මගේ දින දර්ශනය',
    'My profile' => 'මගේ පැතිකඩ',
    'Open the calendar' => 'දින දර්ශනය විවෘත කරන්න',
    'Quiz marks are averaging {pct}% over {n} quiz -- the area to work on.' => 'ප්‍රශ්නාවලි {n}ක ලකුණු සාමාන්‍යය {pct}% -- වැඩි අවධානයක් දිය යුතු කොටස මෙයයි.',
    'Quiz marks are averaging {pct}% over {n} quizzes -- the area to work on.' => 'ප්‍රශ්නාවලි {n}ක ලකුණු සාමාන්‍යය {pct}% -- වැඩි අවධානයක් දිය යුතු කොටස මෙයයි.',
    'Attended {a} of {b} sessions ({pct}%). Missing class is the main gap.' => 'පන්ති {b}න් {a}කට පැමිණ ඇත ({pct}%). පන්ති මඟහැරීම ප්‍රධාන අඩුපාඩුවයි.',
    'Opened {a} of {b} posted items ({pct}%). Working through the material would help.' => 'එකතු කළ අයිතම {b}න් {a}ක් විවෘත කර ඇත ({pct}%). පාඩම් ද්‍රව්‍ය හොඳින් බැලීම උපකාරී වේ.',
    'Strong across marks, attendance and material.' => 'ලකුණු, පැමිණීම සහ පාඩම් ද්‍රව්‍ය සියල්ලෙහිම ශක්තිමත්.',
    '{name} - marks' => '{name} - ලකුණු',
    '{name} - fees' => '{name} - ගාස්තු',

    // Homework, help desk, notices, payment slips, online classes
    'Give the assignment a title, a due date and marks between 1 and 1000.' => 'පැවරුමට මාතෘකාවක්, අවසන් දිනයක් සහ 1ත් 1000ත් අතර ලකුණු ගණනක් දෙන්න.',
    'Assignment published. The class has been told.' => 'පැවරුම ප්‍රකාශයට පත් කළා. පන්තියට දැනුම් දුන්නා.',
    'Saved as a draft.' => 'කෙටුම්පතක් ලෙස සුරැකුණා.',
    'Assignment archived. Hand-ins and marks are kept.' => 'පැවරුම සංරක්ෂණය කළා. භාර දීම් සහ ලකුණු ආරක්ෂිතයි.',
    'Marks must be between 0 and {max}.' => 'ලකුණු 0ත් {max}ත් අතර විය යුතුයි.',
    'That hand-in was not found.' => 'එම භාර දීම හමු නොවීය.',
    'Marks saved.' => 'ලකුණු සුරැකුණා.',
    'This homework has already been marked, so it cannot be changed.' => 'මෙම ගෙදර වැඩට දැනටමත් ලකුණු දමා ඇති නිසා වෙනස් කළ නොහැක.',
    'Write an answer or attach a file before handing in.' => 'භාර දීමට පෙර උත්තරයක් ලියන්න හෝ ගොනුවක් අමුණන්න.',
    'Handed in. It is after the due date, so it is marked late.' => 'භාර දුන්නා. අවසන් දිනයෙන් පසු නිසා ප්‍රමාද ලෙස සටහන් වේ.',
    'Handed in. Well done!' => 'භාර දුන්නා. ඉතා හොඳයි!',
    'No student is linked to this login. Contact the office.' => 'මෙම පිවිසුමට කිසිදු සිසුවෙකු සම්බන්ධ කර නැත. කාර්යාලය අමතන්න.',
    'Settle this month\'s fee to open the class material.' => 'පාඩම් ද්‍රව්‍ය විවෘත කිරීමට මේ මාසයේ ගාස්තුව ගෙවන්න.',
    'That assignment is not available.' => 'එම පැවරුම ලබා ගත නොහැක.',
    'Only the class teacher or an admin can set homework for this class.' => 'මෙම පන්තියට ගෙදර වැඩ දිය හැක්කේ පන්ති ගුරුවරයාට හෝ පරිපාලකට පමණයි.',
    'Write a subject and your message.' => 'මාතෘකාවක් සහ ඔබේ පණිවිඩය ලියන්න.',
    'Choose one of your classes.' => 'ඔබේ පන්තියක් තෝරන්න.',
    'Your question has been sent to the teacher.' => 'ඔබේ ප්‍රශ්නය ගුරුතුමියට යැව්වා.',
    'Your request has been sent to the office.' => 'ඔබේ ඉල්ලීම කාර්යාලයට යැව්වා.',
    'This conversation is closed. Start a new one if you need more help.' => 'මෙම සංවාදය වසා ඇත. තවත් උදව් අවශ්‍ය නම් අලුත් එකක් ආරම්භ කරන්න.',
    'Write your message first.' => 'මුලින්ම ඔබේ පණිවිඩය ලියන්න.',
    'Marked as resolved. Thank you!' => 'විසඳුණු ලෙස සලකුණු කළා. ස්තූතියි!',
    'Reply sent.' => 'පිළිතුර යැව්වා.',
    'That conversation was not found.' => 'එම සංවාදය හමු නොවීය.',
    'Write a title and message, and choose who should see it.' => 'මාතෘකාවක් සහ පණිවිඩයක් ලියා, එය දැකිය යුත්තේ කාටදැයි තෝරන්න.',
    'You can only post notices for your own branch or classes.' => 'ඔබට දැන්වීම් පළ කළ හැක්කේ ඔබේම ශාඛාවට හෝ පන්තිවලට පමණයි.',
    'Scheduled. It appears and is announced at the chosen time.' => 'කාලසටහන්ගත කළා. තෝරාගත් වේලාවට එය පෙන්වා දැනුම් දෙනු ලැබේ.',
    'Published to {n} people.' => '{n} දෙනෙකුට ප්‍රකාශයට පත් කළා.',
    'Notice archived.' => 'දැන්වීම සංරක්ෂණය කළා.',
    'That notice is not yours to change.' => 'එම දැන්වීම ඔබට වෙනස් කළ නොහැක.',
    'That fee is not waiting for payment.' => 'එම ගාස්තුව ගෙවීමට බලා සිටින්නක් නොවේ.',
    'A slip for this fee is already waiting for review.' => 'මෙම ගාස්තුව සඳහා ස්ලිප් පතක් දැනටමත් පරීක්ෂාවට බලා සිටී.',
    'Enter the amount on the slip and the date it was paid.' => 'ස්ලිප් පතේ මුදල සහ ගෙවූ දිනය ඇතුළත් කරන්න.',
    'That bank reference has already been submitted.' => 'එම බැංකු යොමු අංකය දැනටමත් ඉදිරිපත් කර ඇත.',
    'Attach a photo or PDF of the slip.' => 'ස්ලිප් පතේ ඡායාරූපයක් හෝ PDF එකක් අමුණන්න.',
    'Slip sent for review. Note: it is more than the amount due; the office will check it.' => 'ස්ලිප් පත පරීක්ෂාවට යැව්වා. සටහන: එය ගෙවිය යුතු මුදලට වඩා වැඩියි; කාර්යාලය එය පරීක්ෂා කරයි.',
    'Slip sent for review. Your class opens once the office approves it.' => 'ස්ලිප් පත පරීක්ෂාවට යැව්වා. කාර්යාලය අනුමත කළ පසු ඔබේ පන්තිය විවෘත වේ.',
    'This slip has already been reviewed.' => 'මෙම ස්ලිප් පත දැනටමත් පරීක්ෂා කර ඇත.',
    'The approved amount must be more than 0 and no more than the Rs. {n} still due.' => 'අනුමත මුදල 0ට වඩා වැඩි විය යුතු අතර තවමත් ගෙවිය යුතු රු. {n}ට වඩා වැඩි නොවිය යුතුයි.',
    'The slip could not be approved. Nothing was changed.' => 'ස්ලිප් පත අනුමත කළ නොහැකි විය. කිසිවක් වෙනස් නොකළා.',
    'Approved. The fee is now settled.' => 'අනුමත කළා. ගාස්තුව දැන් ගෙවා ඇත.',
    'Approved. Part of the fee is still due.' => 'අනුමත කළා. ගාස්තුවෙන් කොටසක් තවම ගෙවිය යුතුයි.',
    'Give the family a reason for the rejection.' => 'ප්‍රතික්ෂේප කිරීමට හේතුවක් පවුලට දෙන්න.',
    'Rejected. The family has been told why.' => 'ප්‍රතික්ෂේප කළා. හේතුව පවුලට දැනුම් දුන්නා.',
    'That slip is not in your branch.' => 'එම ස්ලිප් පත ඔබේ ශාඛාවට අයත් නැත.',
    'Set an assignment' => 'පැවරුමක් දෙන්න',
    'Assignments' => 'පැවරුම්',
    'Title' => 'මාතෘකාව',
    'Instructions' => 'උපදෙස්',
    'What should the students do? Which pages, which questions?' => 'සිසුන් කළ යුත්තේ මොනවාද? කුමන පිටු, කුමන ප්‍රශ්න?',
    'Out of (marks)' => 'මුළු ලකුණු',
