    'Sat' => 'පිළිතුරු ලියූ',
    'nobody sat' => 'කිසිවෙකු ලියා නැත',
    'Needing attention' => 'අවධානය අවශ්‍ය',
    'Averaging under 50% over two or more quizzes -- not one bad paper.' => 'ප්‍රශ්නාවලි දෙකක් හෝ වැඩි ගණනක සාමාන්‍යය 50%ට අඩු -- එක් නරක ප්‍රශ්න පත්‍රයක් පමණක් නොවේ.',
    'Nobody is below 50% on average.' => 'සාමාන්‍යයෙන් කිසිවෙකු 50%ට අඩු නැත.',
    'Doing best' => 'හොඳින්ම කරන අය',
    'Not enough quizzes sat yet.' => 'තවම ප්‍රමාණවත් ප්‍රශ්නාවලි ලියා නැත.',
    'Upcoming' => 'ඉදිරියට',

    // Seminars advertised on the home page
    'What\'s on' => 'ඉදිරියේදී',
    'Upcoming seminars & events' => 'ඉදිරි සම්මන්ත්‍රණ සහ උත්සව',
    'Ask about this' => 'මේ ගැන විමසන්න',
    'Students: register in the portal' => 'සිසුන්: ද්වාරයෙන් ලියාපදිංචි වන්න',
    'Poster (optional)' => 'පෝස්ටරය (අත්‍යවශ්‍ය නොවේ)',
    'Upload a JPG, PNG or WEBP up to 3MB, or paste an image link below. A wide picture (about 16:9) looks best on the home page.' => '3MB දක්වා JPG, PNG හෝ WEBP රූපයක් උඩුගත කරන්න, නැතහොත් පහතින් රූප සබැඳියක් අලවන්න. පළල් රූපයක් (16:9 පමණ) මුල් පිටුවේ වඩාත් හොඳින් පෙනේ.',
    'Image link' => 'රූප සබැඳිය',
    'Show on the website home page' => 'වෙබ් අඩවියේ මුල් පිටුවේ පෙන්වන්න',
    'Once published, anyone visiting the website sees the title, date, time, venue, branch, poster and description until the day of the event. The online link is never shown there.' => 'ප්‍රකාශයට පත් කළ පසු, උත්සව දිනය දක්වා වෙබ් අඩවියට පැමිණෙන ඕනෑම අයෙකුට මාතෘකාව, දිනය, වේලාව, ස්ථානය, ශාඛාව, පෝස්ටරය සහ විස්තරය පෙනේ. අන්තර්ජාල සබැඳිය කිසිවිටෙක එහි නොපෙන්වයි.',
    'On the website' => 'වෙබ් අඩවියේ',
    'Shown on the home page until the day of the event.' => 'උත්සව දිනය දක්වා මුල් පිටුවේ පෙන්වයි.',
    'Will appear on the home page once published.' => 'ප්‍රකාශයට පත් කළ පසු මුල් පිටුවේ පෙන්වනු ඇත.',
    'The poster could not be uploaded. Please try again.' => 'පෝස්ටරය උඩුගත කළ නොහැකි විය. කරුණාකර නැවත උත්සාහ කරන්න.',
    'The poster must be a JPG, PNG or WEBP image.' => 'පෝස්ටරය JPG, PNG හෝ WEBP රූපයක් විය යුතුය.',
    'The poster must be 3MB or smaller.' => 'පෝස්ටරය 3MB හෝ ඊට අඩු විය යුතුය.',

    // Users page, confirm box
    'User Management' => 'පරිශීලක කළමනාකරණය',
    'Enabled' => 'සක්‍රියයි',
    'Disabled' => 'අක්‍රියයි',
    'Reset Password' => 'මුරපදය යළි සකසන්න',
    'ID Card' => 'හැඳුනුම්පත',
    'Make inactive' => 'අක්‍රිය කරන්න',
    'Activate' => 'සක්‍රිය කරන්න',
    'Yes, continue' => 'ඔව්, ඉදිරියට',
    'This is your own account. Change your details from My Profile.' => 'මෙය ඔබේම ගිණුමයි. ඔබේ විස්තර මගේ පැතිකඩෙන් වෙනස් කරන්න.',
    'Only the super admin can change an admin account.' => 'පරිපාලක ගිණුමක් වෙනස් කළ හැක්කේ ප්‍රධාන පරිපාලකට පමණි.',
    'Works in more than one branch, so only the super admin can change this account.' => 'ශාඛා එකකට වඩා වැඩ කරන නිසා, මෙම ගිණුම වෙනස් කළ හැක්කේ ප්‍රධාන පරිපාලකට පමණි.',
    'Switch off {name}\'s account? They will be signed out and cannot log in until it is switched on again.' => '{name}ගේ ගිණුම අක්‍රිය කරන්නද? ඔවුන් පද්ධතියෙන් ඉවත් වන අතර නැවත සක්‍රිය කරන තුරු පිවිසිය නොහැක.',
    'Delete {name} permanently? This cannot be undone. To keep their history, make the account inactive instead.' => '{name} ස්ථිරවම මකන්නද? මෙය ආපසු හැරවිය නොහැක. ඉතිහාසය තබා ගැනීමට, ගිණුම අක්‍රිය කරන්න.',
    'Delete the class {name}? This cannot be undone.' => '{name} පන්තිය මකන්නද? මෙය ආපසු හැරවිය නොහැක.',
    'Delete the branch {name}? This cannot be undone.' => '{name} ශාඛාව මකන්නද? මෙය ආපසු හැරවිය නොහැක.',
    'Generate monthly invoices for all active enrollments for this period?' => 'මෙම කාලය සඳහා සියලු සක්‍රිය ලියාපදිංචි කිරීම්වලට මාසික ඉන්වොයිස් සාදන්නද?',
    'Mark this payment as paid?' => 'මෙම ගෙවීම ගෙවූ ලෙස සලකුණු කරන්නද?',
    'Confirm payment collection for this month?' => 'මෙම මාසයේ ගෙවීම ලැබුණු බව තහවුරු කරන්නද?',
    'Remove question {n}?' => '{n} වන ප්‍රශ්නය ඉවත් කරන්නද?',
    'Deactivate this guardian\'s login? The student and any other guardian are not affected.' => 'මෙම භාරකරුගේ පිවිසුම අක්‍රිය කරන්නද? සිසුවාට සහ වෙනත් භාරකරුවන්ට බලපෑමක් නැත.',
    'Approve this workflow?' => 'මෙම ඉල්ලීම අනුමත කරන්නද?',
    'Start time' => 'ආරම්භක වේලාව',
    'End time' => 'අවසන් වේලාව',
    'User status updated to Inactive.' => 'පරිශීලකයා අක්‍රිය කරන ලදී.',
    'User status updated to Active.' => 'පරිශීලකයා සක්‍රිය කරන ලදී.',

    // General settings, error pages
    'System Settings' => 'පද්ධති සැකසුම්',
    'General Settings' => 'සාමාන්‍ය සැකසුම්',
    'System Configuration' => 'පද්ධති වින්‍යාසය',
    'Site name' => 'වෙබ් අඩවියේ නම',
    'Shown in the portal header, browser tab and student ID cards. Leave blank to use the teacher\'s name.' => 'ද්වාරයේ ශීර්ෂයේ, බ්‍රවුසර ටැබයේ සහ සිසු හැඳුනුම්පත්වල පෙන්වයි. ගුරුතුමියගේ නම භාවිත කිරීමට හිස්ව තබන්න.',
    'Timezone' => 'කාල කලාපය',
    'Currency' => 'මුදල් ඒකකය',
    'System timezone is fixed to Asia/Colombo' => 'පද්ධතියේ කාල කලාපය Asia/Colombo ලෙස ස්ථිරයි',
    'System currency is fixed to LKR (Sri Lankan Rupees)' => 'පද්ධතියේ මුදල් ඒකකය LKR (ශ්‍රී ලංකා රුපියල්) ලෙස ස්ථිරයි',
    'Admin contact email' => 'පරිපාලක සම්බන්ධතා විද්‍යුත් තැපෑල',
    'Save Settings' => 'සැකසුම් සුරකින්න',
    'Settings updated successfully.' => 'සැකසුම් සාර්ථකව යාවත්කාලීන කරන ලදී.',
    'Site name must be 80 characters or fewer.' => 'වෙබ් අඩවියේ නම අක්ෂර 80කට නොවැඩි විය යුතුය.',
    'Please enter a valid email address.' => 'කරුණාකර වලංගු විද්‍යුත් තැපැල් ලිපිනයක් ඇතුළත් කරන්න.',
    'Page Not Found' => 'පිටුව හමු නොවීය',
    'The page you are looking for does not exist or has been moved.' => 'ඔබ සොයන පිටුව නොපවතී, නැතහොත් වෙනත් තැනකට ගෙන ගොස් ඇත.',
    'Go Home' => 'මුල් පිටුවට',
    'Access Forbidden' => 'ප්‍රවේශය තහනම්',
    'You do not have permission to access this page. Contact your administrator if you believe this is an error.' => 'මෙම පිටුවට පිවිසීමට ඔබට අවසර නැත. මෙය වැරදීමක් යැයි ඔබ සිතන්නේ නම් පරිපාලක අමතන්න.',
    // Class & Enrollment Reports page
    'Class & Enrollment Reports' => 'පන්ති සහ ඇතුළත් කිරීම් වාර්තා',
    'Course capacity, teacher assignment, and student distribution' => 'පාඨමාලා ධාරිතාව, ගුරු පැවරීම සහ සිසුන් බෙදී යෑම',
    'Print Report' => 'වාර්තාව මුද්‍රණය කරන්න',
    'Export to CSV' => 'CSV ලෙස නිර්යාත කරන්න',
    'Institute Filter' => 'ආයතන පෙරහන',
    'All Institutes' => 'සියලුම ආයතන',
    'Total Enrolled Students' => 'ඇතුළත් වූ මුළු සිසුන් ගණන',
    'Average per Class' => 'පන්තියකට සාමාන්‍යය',
