    'That photo is larger than 3 MB. Please choose a smaller one.' => 'එම ඡායාරූපය 3 MB ට වඩා විශාලයි. කරුණාකර කුඩා එකක් තෝරන්න.',
    'Photo must be a JPG, PNG, or WEBP image.' => 'ඡායාරූපය JPG, PNG, හෝ WEBP විය යුතුය.',
    'Could not save the photo. Please try again.' => 'ඡායාරූපය සුරැකිය නොහැකි විය. කරුණාකර නැවත උත්සාහ කරන්න.',
    'Profile photo updated.' => 'පැතිකඩ ඡායාරූපය යාවත්කාලීන කරන ලදී.',
    // Website Ads (standalone promotional banners)
    'Website Ads' => 'වෙබ් අඩවි දැන්වීම්',
    'Promotional banners shown on the public home page, with no event or class behind them. For a specific seminar or event, use the "Show on the website" option when creating it instead.' => 'මහජන මුල් පිටුවේ පෙන්වන ප්‍රවර්ධන දැන්වීම්, කිසිදු සම්මන්ත්‍රණයක් හෝ පන්තියක් නොමැතිව. විශේෂිත සම්මන්ත්‍රණයක් හෝ සිදුවීමක් සඳහා, එය සෑදීමේදී "වෙබ් අඩවියේ පෙන්වන්න" විකල්පය භාවිතා කරන්න.',
    'Always' => 'සැමවිටම',
