    'Add a new ad' => 'නව දැන්වීමක් එක් කරන්න',
    'e.g. 2027 scholarship class enrolment now open' => 'උදා: 2027 ශිෂ්‍යත්ව පන්තියට ඇතුළත් වීම දැන් විවෘතයි',
    'Leave blank for an informational banner with no link.' => 'සබැඳියක් නැති දැනුම්දීම් පටියක් සඳහා මෙය හිස්ව තබන්න.',
