    'Could not save the uploaded photo.' => 'උඩුගත කළ ඡායාරූපය සුරැකිය නොහැකි විය.',
    'The link must be a full http:// or https:// address.' => 'සබැඳිය සම්පූර්ණ http:// හෝ https:// ලිපිනයක් විය යුතුය.',
    'Dates must be in YYYY-MM-DD form.' => 'දිනයන් YYYY-MM-DD ආකාරයෙන් විය යුතුය.',
    'The start date must be on or before the end date.' => 'ආරම්භක දිනය අවසන් දිනයට පෙර හෝ එදිනම විය යුතුය.',
    // Teacher-facing pages: teaching hub, materials, quizzes, attendance
    'Papers to mark' => 'වකුම් කටයුතු ඇති ප්‍රශ්න පත්‍ර',
    'Unpaid this month' => 'මෙම මාසයේ නොගෙවූ',
