    'Material posted' => 'පළ කළ ඉවදාම්',
    'Quizzes live' => 'ක්‍රියාත්මක ප්‍රශ්නාවලි',
    'No classes assigned yet' => 'තවම පන්ති පවරා නැත',
    'Classes you teach will appear here.' => 'ඔබ ඉගැන්වන පන්ති මෙහි පෙනෙනු ඇත.',
    'material' => 'ඉවදාම්',
    'quizzes' => 'ප්‍රශ්නාවලි',
    'unpaid' => 'නොගෙවූ',
    'Class material' => 'පන්ති ඉවදාම්',
