    'Post the lesson recording, the notes and any video you want the class to have.' => 'පාඩම් පටිගත කිරීම, සටහන් සහ පන්තියට තිබිය යුතු ඕනෑම වීඩියෝවක් පළ කරන්න.',
    'Post the first item' => 'පළමු අයිතමය පළ කරන්න',
    'Item' => 'අයිතමය',
    'Opened by' => 'විවෘත කළ සංඛ්‍යාව',
    'Download' => 'බාගත කරන්න',
    'Students who have settled this month\'s fee can open everything below.' => 'මෙම මාසයේ ගාස්තුව ගෙවූ ශිෂ්‍යයන්ට පහත සියල්ල විවෘත කළ හැක.',
    'Length (minutes)' => 'කාල සීමාව (මිනිත්තු)',
    'Where is it?' => 'එය තිබෙන්නේ කොහේද?',
    'A link or a file — one or the other. Zoom recordings and YouTube videos belong on a link; notes and past papers are better uploaded.' => 'සබැඳියක් හෝ ගොනුවක් — එකක් හෝ තවත් එකක්. Zoom පටිගත කිරීම් සහ YouTube වීඩියෝ සබැඳියක් ලෙස වඩාත් සුදුසුයි; සටහන් සහ පැරණි ප්‍රශ්න පත්‍ර උඩුගත කිරීම වඩා සුදුසුයි.',
    'or' => 'හෝ',
    'Upload a file' => 'ගොනුවක් උඩුගත කරන්න',
    'PDF, PNG or JPG, up to 20 MB. Put larger videos on a link instead.' => 'PDF, PNG හෝ JPG, උපරිම 20 MB. වඩා විශාල වීඩියෝ සබැඳියක් ලෙස එක් කරන්න.',
    'Post it' => 'පළ කරන්න',
    'Students who settled this month\'s fee can open it.' => 'මෙම මාසයේ ගාස්තුව ගෙවූ ශිෂ්‍යයන්ට එය විවෘත කළ හැක.',
    'Set a quiz' => 'ප්‍රශ්නාවලියක් සකසන්න',
    'Set a paper, add the questions, then publish it. Students sit it inside the window you choose.' => 'ප්‍රශ්න පත්‍රයක් සකසා, ප්‍රශ්න එක් කර, පසුව එය ප්‍රකාශයට පත් කරන්න. ඔබ තෝරන කාල සීමාව තුළ ශිෂ්‍යයන් එය සිදු කරයි.',
    'Set the first quiz' => 'පළමු ප්‍රශ්නාවලිය සකසන්න',
    'Window' => 'කාල සීමාව',
    'Questions' => 'ප්‍රශ්න',
    'waiting on you' => 'ඔබගේ අවධානය සඳහා පොරොත්තුවෙන්',
    'Results' => 'ප්‍රතිඵල',
    'For' => 'සඳහා',
    'When can they sit it?' => 'ඔවුන්ට එය කවදා සිදු කළ හැකිද?',
    'Students can only start inside this window. The time limit then caps one sitting — a paper started five minutes before closing still gets its full time, up to the closing moment.' => 'ශිෂ්‍යයන්ට මෙම කාල සීමාව තුළ පමණක් ආරම්භ කළ හැක. කාල සීමාව එක් වාරයක් සීමා කරයි — වසා දැමීමට මිනිත්තු පහකට පෙර ආරම්භ කළ ප්‍රශ්න පත්‍රයක් වසා දැමෙන මොහොත දක්වා එහි සම්පූර්ණ කාලය ලබා ගනී.',
    'Opens' => 'විවෘත වේ',
    'Closes' => 'වසා දැමේ',
    'Time limit (minutes)' => 'කාල සීමාව (මිනිත්තු)',
    'Only students who settled it can sit the quiz.' => 'එය ගෙවූ ශිෂ්‍යයන්ට පමණක් ප්‍රශ්නාවලිය සිදු කළ හැක.',
    'Pass mark (%)' => 'සමත් ලකුණු (%)',
    'Attempts allowed' => 'අවසර ඇති උත්සාහයන්',
    'Shuffle the question order for each student' => 'සෑම ශිෂ්‍යයෙකු සඳහාම ප්‍රශ්න අනුපිළිවෙල මුසු කරන්න',
    'Show the correct answers once the quiz closes' => 'ප්‍රශ්නාවලිය වසා දැමූ පසු නිවැරදි පිළිතුරු පෙන්වන්න',
    'You add the questions on the next screen, then publish when it is ready. Students cannot see a draft.' => 'ඊළඟ තිරයේ ඔබ ප්‍රශ්න එක් කරයි, පසුව එය සූදානම් වූ විට ප්‍රකාශයට පත් කරන්න. කෙටුම්පතක් ශිෂ්‍යයන්ට දැක ගත නොහැක.',
