    // Self-service forgotten password
    'Type your login ID and we will send a reset code to the mobile number registered on your account. The code works once, for 30 minutes.' => 'ඔබගේ පිවිසුම් අංකය ටයිප් කරන්න, එවිට ඔබගේ ගිණුමට ලියාපදිංචි කර ඇති ජංගම දුරකථන අංකයට යළි සැකසීමේ කේතයක් එවනු ලැබේ. එම කේතය මිනිත්තු 30ක් ඇතුළත එක් වරක් පමණක් වැඩ කරයි.',
    'Send me a reset code' => 'යළි සැකසීමේ කේතයක් එවන්න',
    'No mobile number on your account, or the number has changed? Call the branch office and they will give you a code after confirming who you are.' => 'ඔබගේ ගිණුමේ ජංගම දුරකථන අංකයක් නැද්ද, නැතහොත් අංකය වෙනස් වී තිබේද? ශාඛා කාර්යාලයට අමතන්න, ඔබ කවුදැයි තහවුරු කිරීමෙන් පසු ඔවුන් ඔබට කේතයක් ලබා දෙනු ඇත.',
    'I already have a code' => 'මා සතුව දැනටමත් කේතයක් තිබේ',
    'Too many requests. Please wait 15 minutes and try again.' => 'ඉල්ලීම් ගණන වැඩියි. මිනිත්තු 15ක් රැඳී සිට නැවත උත්සාහ කරන්න.',
    'If that ID is on our records, a reset code is on its way to the phone number registered for it. It works once, for 30 minutes.' => 'එම අංකය අපගේ වාර්තාවල ඇත්නම්, ඒ සඳහා ලියාපදිංචි කර ඇති දුරකථන අංකයට යළි සැකසීමේ කේතයක් එවනු ලැබේ. එය මිනිත්තු 30ක් ඇතුළත එක් වරක් පමණක් වැඩ කරයි.',
    'Hello {name}. Your reset code for the class portal is {code}. It works once, within 30 minutes. If you did not ask for this, please tell the office.' => 'ආයුබෝවන් {name}. පන්ති ද්වාරය සඳහා ඔබගේ යළි සැකසීමේ කේතය {code} වේ. එය මිනිත්තු 30ක් ඇතුළත එක් වරක් පමණක් වැඩ කරයි. ඔබ මෙය ඉල්ලා නොසිටියේ නම්, කරුණාකර කාර්යාලයට දන්වන්න.',

    // Contact page: branch maps and online links
    'Map of {branch}' => '{branch} ශාඛාවේ සිතියම',
    'Find us online' => 'අන්තර්ජාලයෙන් අප හමුවන්න',
    'Facebook' => 'ෆේස්බුක්',

    // Institute form: map link
    'Google Maps link' => 'Google Maps සබැඳිය',
    'Optional. Paste the Google Maps link for the building so the contact page pins it exactly. Left blank, the map searches for the branch name and town.' => 'විකල්පයි. ගොඩනැගිල්ලේ Google Maps සබැඳිය මෙහි අලවන්න, එවිට අමතන්න පිටුවේ සිතියම හරියටම එතැන සලකුණු කරයි. හිස්ව තැබුවොත්, ශාඛාවේ නම සහ නගරය අනුව සිතියම සොයයි.',
    'Sepala - Pannipitiya' => 'සේපාල - පන්නිපිටිය',
    'Sarasavi - Manawila, Galle' => 'සරසවි - මානවිල, ගාල්ල',
    'Riyal - Pitipana, Homagama' => 'රියල් - පිටිපන, හෝමාගම',
    'Pannipitiya' => 'පන්නිපිටිය',
    'Manawila, Galle' => 'මානවිල, ගාල්ල',
    'Pitipana, Homagama' => 'පිටිපන, හෝමාගම',
    'Grade 6 Science - Pannipitiya' => '6 ශ්‍රේණිය විද්‍යාව - පන්නිපිටිය',
    'Grade 7 Science - Pannipitiya' => '7 ශ්‍රේණිය විද්‍යාව - පන්නිපිටිය',
    'Grade 8 Science - Pannipitiya' => '8 ශ්‍රේණිය විද්‍යාව - පන්නිපිටිය',
    'Grade 9 Science - Pannipitiya' => '9 ශ්‍රේණිය විද්‍යාව - පන්නිපිටිය',
    'Grade 10 Science - Pannipitiya' => '10 ශ්‍රේණිය විද්‍යාව - පන්නිපිටිය',
    'Grade 11 Science - Pannipitiya' => '11 ශ්‍රේණිය විද්‍යාව - පන්නිපිටිය',
    'Grade 6 Science - Galle' => '6 ශ්‍රේණිය විද්‍යාව - ගාල්ල',
    'Grade 7 Science - Galle' => '7 ශ්‍රේණිය විද්‍යාව - ගාල්ල',
    'Grade 8 Science - Galle' => '8 ශ්‍රේණිය විද්‍යාව - ගාල්ල',
    'Grade 9 Science - Galle' => '9 ශ්‍රේණිය විද්‍යාව - ගාල්ල',
    'Grade 10 Science - Galle' => '10 ශ්‍රේණිය විද්‍යාව - ගාල්ල',
    'Grade 11 Science - Galle' => '11 ශ්‍රේණිය විද්‍යාව - ගාල්ල',
    'Grade 9 Science - Homagama' => '9 ශ්‍රේණිය විද්‍යාව - හෝමාගම',
    'Grade 10 Science - Homagama' => '10 ශ්‍රේණිය විද්‍යාව - හෝමාගම',
    'Grade 11 Science - Homagama' => '11 ශ්‍රේණිය විද්‍යාව - හෝමාගම',
    'Grade 11' => '11 ශ්‍රේණිය',
    'Open the help bot' => 'උදව් බොට් එක විවෘත කරන්න',
    'Help bot' => 'උදව් බොට්',
    'Ask us anything' => 'ඕනම දෙයක් අහන්න',
    'Fees, timetable, branches, joining' => 'ගාස්තු, කාලසටහන, ශාඛා, ඇතුළත් වීම',
    'Ask about fees, classes, branches...' => 'ගාස්තු, පන්ති, ශාඛා ගැන අහන්න...',
    'Ask me about fees, class times, branches, joining, or your password — or tap one of the quick questions below.' => 'ගාස්තු, පන්ති වෙලාවන්, ශාඛා, ඇතුළත් වීම, හෝ ඔබගේ මුරපදය ගැන මගෙන් අහන්න — නැතහොත් පහත ඇති ඉක්මන් ප්‍රශ්නයක් touch කරන්න.',
    'Ayubowan! I can help with fees, class times, branches, joining a class, or resetting a password. What would you like to know?' => 'ආයුබෝවන්! මට ගාස්තු, පන්ති වෙලාවන්, ශාඛා, පන්තියකට ඇතුළත් වීම, හෝ මුරපදය යළි සකස් කිරීම ගැන උදව් කළ හැකියි. ඔබ දැනගන්න කැමති කුමක්ද?',
    'Full class days and times, by branch and grade, are on the timetable page.' => 'ශාඛාව සහ ශ්‍රේණිය අනුව සම්පූර්ණ පන්ති දින සහ වෙලාවන් කාලසටහන් පිටුවේ තිබේ.',
    'View timetable' => 'කාලසටහන බලන්න',
    'Send the inquiry form, or call your nearest branch. The office registers the student and gives a student ID and password for the portal.' => 'විමසීම් පත්‍රය එවන්න, නැතහොත් ඔබේ ළගම ශාඛාවට කතා කරන්න. කාර්යාලය ශිෂ්‍යයා ලියාපදිංචි කර ද්වාරය සඳහා ශිෂ්‍ය හැඳුනුම්පතක් සහ මුරපදයක් ලබා දෙයි.',
    'Contact a branch' => 'ශාඛාවකට කතා කරන්න',
    'Tap "Forgot password" on the login page. We text a one-time code to the phone number on file, then you can set a new password right away.' => 'login පිටුවේ "මුරපදය අමතකද?" touch කරන්න. ලියාපදිංචි දුරකථන අංකයට එක් වර කේතයක් එවනවා, එතකොට ඔබට ක්ෂණිකව අලුත් මුරපදයක් සකස් කරගත හැකියි.',
    'Reset password' => 'මුරපදය යළි සකස් කරන්න',
    'If a class is delivered online, the join link appears on your dashboard a little before the session starts — log in and look for the "Join class" button.' => 'පන්තියක් online කරනවා නම්, පන්තිය පටන් ගැනීමට ටික කලකට පෙර join link එක ඔබේ dashboard එකේ පෙනී සිටිනවා — login වී "Join class" බට්න් එක සොයා ගන්න.',
    'Log in' => 'පිවිසෙන්න',
    'The monthly fee is Rs. {amount}, paid at the branch office or by bank slip upload in the portal.' => 'මාසික ගාස්තුව රු. {amount}කි, ශාඛා කාර්යාලයේදී හෝ ද්වාරයේ බැංකු රිසිට්පත upload කර ගෙවිය හැක.',
    'Monthly fees range from Rs. {lo} to Rs. {hi} depending on the grade/class, paid at the branch or by bank slip upload in the portal.' => 'ශ්‍රේණිය/පන්තිය අනුව මාසික ගාස්තු රු. {lo} සිට රු. {hi} දක්වා වේ, ශාඛාවේදී හෝ ද්වාරයේ බැංකු රිසිට්පත upload කර ගෙවිය හැක.',
    'View timetable & fees' => 'කාලසටහන සහ ගාස්තු බලන්න',
    'Fees vary by grade — please check the timetable page or ask your branch.' => 'ගාස්තු ශ්‍රේණිය අනුව වෙනස් වේ — කරුණාකර කාලසටහන් පිටුව බලන්න නැතහොත් ඔබේ ශාඛාවෙන් විමසන්න.',
    'Please see the contact page for our branch addresses.' => 'අපේ ශාඛා පිහිටීම් සඳහා අප පිටුව බලන්න.',
    'We have classes at: {names}.' => 'අපට පන්ති පැවැත්වෙන ස්ථාන: {names}.',
    'View branches & map' => 'ශාඛා සහ සිතියම බලන්න',
    'WhatsApp: {wa}' => 'WhatsApp: {wa}',
    'Email: {email}' => 'ඊ-තැපැල්: {email}',
    'Please see the contact page for phone numbers for each branch.' => 'සියලු ශාඛාවල දුරකතන අංක සඳහා අප පිටුව බලන්න.',
    'Please see the About page for teacher details.' => 'ආචාර්ය තුමිය පිළිබඳ විස්තර සඳහා අප පිටුව බලන්න.',
    'Classes are taught by {name}.' => 'පන්ති පවත්වන්නේ {name} ආචාර්ය තුමිය විසින්.',
    'Read more' => 'තවදුරියත කියවන්න',
    'Sorry, I did not quite catch that. You can ask about fees, timetable, branches, joining, or a forgotten password — or message us directly on WhatsApp: {wa}.' => 'සමාවන්න, මට ඔක තේරුම් ගන්න බැරි ඉය. ඔබට ගාස්තු, කාලසටහන, ශාඛා, ඇතුළත් වීම, හෝ මුරපදය අමතක වීම ගැන අහන්න පුළුවනි — නැතහෝත් WhatsApp වෙතින් අපට පිවිසෙන්න: {wa}.',
    'Sorry, I did not quite catch that. You can ask about fees, timetable, branches, joining, or a forgotten password — or use the contact page.' => 'සමාවන්න, මට ඔක තේරුම් ගන්න බැරි ඉය. ඔබට ගාස්තු, කාලසටහන, ශාඛා, ඇතුළත් වීම, හෝ මුරපදය අමතක වීම ගැන අහන්න පුළුවනි — නැතහෝත් අප පිටුව බ්රවුස් කරන්න.',
    'Upcoming Seminars' => 'පැමිණෙන සේමිනාර',
    'Special seminars and workshops for students and parents' => 'සිසුන් සහ දෙමාපියන් සඳහා විශේෂ සේමිනාර සහ පිරිස්සිදීම්',
    'View details' => 'විස්තර බලන්න',
    'Back to home' => 'ප්‍රධාන පිටුවට',
    'Seminar' => 'සේමිනාරය',
    'Bold' => 'තද අකුරු',
    'Italic' => 'ඇල අකුරු',
    'Underline' => 'යටින් ඉර',
    'Bulleted list' => 'බුලට් ලැයිස්තුව',
    'Numbered list' => 'අංකිත ලැයිස්තුව',
    'Formatting' => 'හැඩතල ගැසීම',
    'Link URL (https://...)' => 'සබැඳි ලිපිනය (https://...)',
    'Remove link' => 'සබැඳිය ඉවත් කරන්න',
    'Remove this photo and use the original instead' => 'මෙම ඡායාරූපය ඉවත් කර මුල් ඡායාරූපය භාවිත කරන්න',
    'Using the original photo' => 'මුල් ඡායාරූපය භාවිත කරමින්',
    'Not shown unless filled in' => 'පුරවන තෙක් පෙනෙන්නේ නැත',
    'Classes, quizzes and tests together' => 'පන්ති, ප්‍රශ්නාවලි සහ පරීක්ෂණ එකට',
    'Add a test or exam' => 'පරීක්ෂණයක් හෝ විභාගයක් එකතු කරන්න',
    'Reminders' => 'මතක් කිරීම්',
    'Everyone gets a reminder a day before and again an hour before, in their notifications. The scheduled job does this on its own; press this only if you have just added something for tomorrow. Pressing it twice sends nothing twice.' => 'සෑම කෙනෙකුටම දිනකට පෙර සහ පැයකට පෙර නැවතත් ඔවුන්ගේ දැනුම්දීම්වල මතක් කිරීමක් ලැබේ. කාලසටහන්ගත කාර්යය මෙය තනිවම සිදු කරයි; හෙට සඳහා යමක් එකතු කර ඇත්නම් පමණක් මෙය ඔබන්න. දෙවතාවක් ඔබුවත් දෙවතාවක් යවන්නේ නැත.',
    'Send what is due now' => 'දැන් යැවිය යුතු දෑ යවන්න',
    'Put something on the calendar' => 'දින දර්ශනයට යමක් එකතු කරන්න',
    'What is it' => 'එය කුමක්ද',
    'Class cancelled' => 'පන්තිය අවලංගු කරන ලදී',
    'Everyone (holiday or school-wide notice)' => 'සියලුම දෙනා (නිවාඩුව හෝ පාසල පුරා දැන්වීමක්)',
    'Starts' => 'ආරම්භය',
    'Ends' => 'අවසානය',
    'What it covers' => 'එයින් ආවරණය වන දෑ',
    'Remind everyone a day before and an hour before' => 'දිනකට පෙරත් පැයකට පෙරත් සැමට මතක් කරන්න',
    'Add it' => 'එකතු කරන්න',
    'Class times come from each class\'s own schedule and quizzes from their open and close times — they are read, never copied, so moving a class moves it here too. Only tests, exams, extra classes, cancellations, holidays and notices are entered on this page.' => 'පන්ති කාලයන් එක් එක් පන්තියේම කාලසටහනෙනුත් ප්‍රශ්නාවලි ඒවායේ විවෘත සහ වසන කාලයන්ගෙනුත් ලැබේ — ඒවා කියවනු මිස පිටපත් නොකරනු ලැබේ, එබැවින් පන්තියක් ගෙනයාම මෙහිද එය ගෙනයයි. පරීක්ෂණ, විභාග, අතිරේක පන්ති, අවලංගු කිරීම්, නිවාඩු සහ දැන්වීම් පමණක් මෙම පිටුවේ ඇතුළත් කරනු ලැබේ.',
    'QR Scan Entrance Terminal' => 'QR ස්කෑන් ප්‍රවේශ පර්යන්තය',
    'Automated student gate & classroom attendance scanner' => 'ස්වයංක්‍රීය ශිෂ්‍ය ගේට්ටු සහ පන්ති පැමිණීම් ස්කෑනරය',
    'View Attendance Sheet' => 'පැමිණීම් පත්‍රය බලන්න',
    'Active Classroom / Session:' => 'ක්‍රියාත්මක පන්තිය / සැසිය:',
    '-- All Active Classes / Entrance Gate --' => '-- සියලුම ක්‍රියාත්මක පන්ති / ප්‍රවේශ ගේට්ටුව --',
    'Terminal Ready' => 'පර්යන්තය සූදානම්',
    'Test 5s Loud Alert Sound' => 'තත්පර 5 හඬ අනතුරු ඇඟවීම පරීක්ෂා කරන්න',
    'Test Siren' => 'සයිරන් පරීක්ෂා කරන්න',
    'Scan QR Card or Enter Student ID (e.g. STU20260001)...' => 'QR කාඩ්පත ස්කෑන් කරන්න හෝ ශිෂ්‍ය හැඳුනුම්පත ඇතුළත් කරන්න (උදා. STU20260001)...',
    'Verify' => 'තහවුරු කරන්න',
    'Scanner hardware will automatically trigger on barcode / QR swipe.' => 'බාර්කෝඩ් / QR ස්වයිප් කිරීමේදී ස්කෑනර් උපකරණය ස්වයංක්‍රීයව ක්‍රියාත්මක වේ.',
    'Present QR Code' => 'QR කෝඩය ඉදිරිපත් කරන්න',
    'Ready for input' => 'ඇතුළත් කිරීම සඳහා සූදානම්',
    'Live Terminal Feed' => 'සජීවී පර්යන්ත සංග්‍රහය',
    'Scans' => 'ස්කෑන්',
    'Waiting for scans...' => 'ස්කෑන් සඳහා රැඳී සිටී...',
    'Student attendance scans will appear here live.' => 'ශිෂ්‍ය පැමිණීම් ස්කෑන් මෙහි සජීවීව පෙනෙනු ඇත.',
    'Account Deactivated' => 'ගිණුම අක්‍රිය කර ඇත',
    'Your account has been automatically deactivated because the monthly fee was not received within the 21-day grace period. Please make a payment to reactivate your access.' => 'ඔබගේ ගිණුම මාසික ගාස්තුව දින 21 සහන කාලය තුළ නොගෙවූ බැවින් ස්වයංක්‍රීයව අක්‍රිය කර ඇත. ප්‍රවේශය නැවත සක්‍රීය කිරීම සඳහා ගෙවීමක් කරන්න.',
    'Attendance Marked with RED FLAG in System Logs' => 'පැමිණීම පද්ධති ලඝු-සටහන් වල රතු සලකුණකින් සලකුණු කර ඇත',
    'Acknowledge & Silence Siren' => 'පිළිගන්න සහ සයිරනය නිශ්ශබ්ද කරන්න',
    'Scan error.' => 'ස්කෑන් දෝෂයකි.',
    '5-Second Siren Test playing!' => 'තත්පර 5 සයිරන පරීක්ෂණය ක්‍රියාත්මක වේ!',
    'Select Role to Configure:' => 'සැකසීමට භූමිකාව තෝරන්න:',
    'Currently editing:' => 'දැනට සංස්කරණය කරමින්:',
    'Features for {role}' => '{role} සඳහා විශේෂාංග',
    'Show All' => 'සියල්ල පෙන්වන්න',
    'Hide All' => 'සියල්ල සඟවන්න',
    'No role-specific features are offered for this role.' => 'මෙම භූමිකාව සඳහා විශේෂිත විශේෂාංග නොමැත.',
    'Feature' => 'විශේෂාංගය',
    'Visible' => 'දිස්වේ',
    'Hidden' => 'සැඟවී ඇත',
    'Changes take effect immediately upon saving, and only affect what this role sees in the sidebar.' => 'වෙනස්කම් සුරැකීමෙන් වහාම ක්‍රියාත්මක වන අතර, මෙම භූමිකාව පැති තීරුවේ දකින දෑ පමණක් බලපායි.',
    'Save Feature Visibility' => 'විශේෂාංග දෘශ්‍යතාව සුරකින්න',
