    'Automatic Scholarship Logic Applied' => 'ස්වයංක්‍රීය ශිෂ්‍යත්ව තර්කනය යොදා ඇත',
    'Full Payment students are invoiced at 100% of class fee.' => 'සම්පූර්ණ ගෙවීම් ශිෂ්‍යයින්ට පන්ති ගාස්තුවෙන් 100%ක් ඉන්වොයිස් කරනු ලැබේ.',
    'Half Payment (50%) students are invoiced at 50% discount.' => 'අර්ධ ගෙවීම් (50%) ශිෂ්‍යයින්ට 50% වට්ටමකින් ඉන්වොයිස් කරනු ලැබේ.',
    'Free Card (100%) students are generated with LKR 0.00 amount due.' => 'නොමිලේ කාඩ්පත් (100%) ශිෂ්‍යයින් සඳහා ගෙවිය යුතු මුදල රු. 0.00 ලෙස ජනනය කරනු ලැබේ.',
    'Generate Invoices' => 'ඉන්වොයිස් ජනනය කරන්න',
