    'Finish and go back to the editor' => 'අවසන් කර සංස්කාරකයට ආපසු යන්න',
    'this is how the site would look. Nothing has been saved yet, and visitors still see the live version.'
        => 'වෙබ් අඩවිය පෙනෙන්නේ මෙලෙසයි. තවම කිසිවක් සුරකින ලද්දේ නැත, අමුත්තන්ට තවමත් පෙනෙන්නේ සජීවී අනුවාදයයි.',

    "One month's class fee has not been paid yet" => 'එක් මසක පන්ති ගාස්තුව තවම ගෙවා නැත',
    '{n} months of class fees have not been paid yet' => 'මාස {n} ක පන්ති ගාස්තු තවම ගෙවා නැත',
    'Please settle this at the branch office. Classes, attendance and the portal are not affected -- this is a reminder, not a block.'
        => 'කරුණාකර මෙය ශාඛා කාර්යාලයේ ගෙවා අවසන් කරන්න. පන්ති, පැමිණීම සහ ද්වාරය මෙයින් බලපෑමකට ලක් නොවේ -- මෙය මතක් කිරීමක් පමණි, වැළැක්වීමක් නොවේ.',

    'Explore our classes' => 'අපගේ පන්ති ගවේෂණය කරන්න',
    'Every branch, grade, day and time -- pick a branch and see its full class list.'
        => 'සෑම ශාඛාවක්, ශ්‍රේණියක්, දිනයක් සහ වේලාවක් -- ශාඛාවක් තෝරා එහි සම්පූර්ණ පන්ති ලැයිස්තුව බලන්න.',
    'Fill the enrol form (pick a branch and class, upload your bank deposit slip) and the branch office approves it -- or send an inquiry below and the office will call you back. Either way you get a student ID and password for the portal.'
        => 'ලියාපදිංචි පෝරමය සම්පූර්ණ කරන්න (ශාඛාවක් සහ පන්තියක් තෝරා, බැංකු තැන්පතු පත්‍රිකාව උඩුගත කරන්න), ශාඛා කාර්යාලය එය අනුමත කරයි -- නැතහොත් පහතින් විමසීමක් එවන්න, කාර්යාලයෙන් ඔබට ආපසු කතා කරනු ලැබේ. කුමන ක්‍රමයෙන් වුවද ඔබට ද්වාරය සඳහා සිසු අංකයක් සහ මුරපදයක් ලැබේ.',

    // ---- Staff screens -------------------------------------------------
    // The admin, teacher and office side. Filled after the public and
    // family pages reached full coverage: a Sinhala-medium teacher or
    // clerk was still reading these in English. Found by
    // tests/lang_coverage.php --all; run it again after adding a screen.
    '"From" email address' => 'යවන්නාගේ විද්‍යුත් තැපැල් ලිපිනය',
    '"From" name' => 'යවන්නාගේ නම',
    '-- Select class --' => '-- පන්තිය තෝරන්න --',
    '1 in use' => 'එකක් භාවිතයේ',
    'A class\'s students' => 'පන්තියේ සිසුන්',
    'A style only fills in the boxes below -- you can still change any single colour afterwards.' => 'මෝස්තරයක් කරන්නේ පහත කොටු පිරවීම පමණි -- ඉන්පසුත් ඕනෑම එක් වර්ණයක් වෙනස් කළ හැකිය.',
    'A temporary password will be generated and shown once, the same way it is for a new student.' => 'නව සිසුවෙකුට මෙන්ම, තාවකාලික මුරපදයක් සාදා එක් වරක් පමණක් පෙන්වනු ලැබේ.',
    'API Key / Bearer Token' => 'API යතුර / Bearer ටෝකනය',
    'API Token / Secret Key' => 'API ටෝකනය / රහස් යතුර',
    'Absent Count' => 'නොපැමිණි ගණන',
    'Add a download' => 'බාගත කිරීමක් එක් කරන්න',
    'Add a guardian' => 'භාරකරුවෙකු එක් කරන්න',
    'Add a new slide' => 'නව රූපයක් එක් කරන්න',
    'Add another guardian' => 'තවත් භාරකරුවෙකු එක් කරන්න',
    'Add download' => 'බාගත කිරීම එක් කරන්න',
    'Add guardian' => 'භාරකරු එක් කරන්න',
    'Add slide' => 'රූපය එක් කරන්න',
    'Allow sending login details by email' => 'පිවිසුම් විස්තර විද්‍යුත් තැපෑලෙන් යැවීමට ඉඩ දෙන්න',
    'Already emailed automatically' => 'දැනටමත් ස්වයංක්‍රීයව විද්‍යුත් තැපෑලෙන් යවා ඇත',
    'Also notify their parents' => 'දෙමාපියන්ටද දැනුම් දෙන්න',
    'Also show as a popup on every public page (once per visit)' => 'සෑම පොදු පිටුවකම උත්පතන දැන්වීමක් ලෙසද පෙන්වන්න (පැමිණීමකට වරක්)',
    'Approve & Register' => 'අනුමත කර ලියාපදිංචි කරන්න',
    'Approved. Student ID: {id}. Could not auto-email the login details -- send them from this screen instead.' => 'අනුමතයි. සිසු අංකය: {id}. පිවිසුම් විස්තර ස්වයංක්‍රීයව විද්‍යුත් තැපෑලෙන් යැවිය නොහැකි විය -- ඒ වෙනුවට මෙම තිරයෙන් යවන්න.',
    'Approved. Student ID: {id}. Login details emailed to the guardian automatically.' => 'අනුමතයි. සිසු අංකය: {id}. පිවිසුම් විස්තර භාරකරුට ස්වයංක්‍රීයව විද්‍යුත් තැපෑලෙන් යවන ලදී.',
    'Assign' => 'පවරන්න',
    'Assign hall' => 'ශාලාව පවරන්න',
    'Background' => 'පසුබිම',
    'Branch photo (shown on the public website)' => 'ශාඛාවේ ඡායාරූපය (පොදු වෙබ් අඩවියේ පෙන්වයි)',
    'Button' => 'බොත්තම',
    'Button wording' => 'බොත්තමේ වචන',
    'Centre it' => 'මැදට ගන්න',
    'Change Your Password' => 'ඔබේ මුරපදය වෙනස් කරන්න',
    'Change the exact wording shown anywhere on the site -- navigation labels, buttons, headings, any fixed text -- in English and/or Sinhala, without a code change.' => 'වෙබ් අඩවියේ ඕනෑම තැනක පෙන්වන වචන -- මෙනු නම්, බොත්තම්, ශීර්ෂ, ඕනෑම ස්ථිර පෙළක් -- ඉංග්‍රීසි සහ/හෝ සිංහල භාෂාවෙන්, කේතය වෙනස් නොකර වෙනස් කරන්න.',
    'Changing the phone number changes which number this guardian logs in with.' => 'දුරකථන අංකය වෙනස් කිරීමෙන් මෙම භාරකරු පිවිසෙන අංකයද වෙනස් වේ.',
    'Choose a photo or video above to set this by eye.' => 'මෙය ඇසින් බලා සැකසීමට ඉහතින් ඡායාරූපයක් හෝ වීඩියෝවක් තෝරන්න.',
    'Class Portal' => 'පන්ති ද්වාරය',
    'Classes & Scholarship Type' => 'පන්ති සහ ශිෂ්‍යත්ව වර්ගය',
    'Click one to see it on the boxes below, then press Save changes to put it live. Nothing changes on the public site until you save, so try as many as you like.' => 'පහත කොටු වල බැලීමට එකක් ක්ලික් කර, සජීවී කිරීමට "වෙනස්කම් සුරකින්න" ඔබන්න. සුරකින තුරු පොදු වෙබ් අඩවියේ කිසිවක් වෙනස් නොවේ, එබැවින් කැමති තරම් උත්සාහ කරන්න.',
    'Click the part of the picture that must stay visible' => 'පෙනෙන්නට තිබිය යුතු රූපයේ කොටස ක්ලික් කරන්න',
    'Click the part of the picture that must stay visible. Phones and wide screens crop it differently, so this is the point they all keep.' => 'පෙනෙන්නට තිබිය යුතු රූපයේ කොටස ක්ලික් කරන්න. දුරකථන සහ පළල් තිර එය වෙනස් ලෙස කපයි, එබැවින් සියල්ලම තබාගන්නේ මෙම ලක්ෂ්‍යයයි.',
    'Clicking send launches the installed WhatsApp application.' => 'යවන්න ක්ලික් කිරීමෙන් ස්ථාපිත WhatsApp යෙදුම විවෘත වේ.',
    'Clicking send opens WhatsApp Web directly in a browser tab.' => 'යවන්න ක්ලික් කිරීමෙන් WhatsApp Web කෙලින්ම බ්‍රව්සර ටැබ් එකක විවෘත වේ.',
    'Collected (Rs.)' => 'එකතු කරගත් මුදල (රු.)',
    'Colours' => 'වර්ණ',
    'Compatible with all phones, tablets, and desktop browsers.' => 'සියලුම දුරකථන, ටැබ්ලට් සහ පරිගණක බ්‍රව්සර සමඟ ගැළපේ.',
    'Compatible with self-hosted WhatsApp clients (Baileys, WPPConnect, Evolution API) or cloud services (UltraMsg, GreenAPI).' => 'ඔබම ධාවනය කරන WhatsApp සේවාදායක (Baileys, WPPConnect, Evolution API) හෝ cloud සේවා (UltraMsg, GreenAPI) සමඟ ගැළපේ.',
    'Configure how the LMS interacts with WhatsApp for fee reminders, alerts, and communications. You can use direct web/desktop links or connect a custom WA Client API gateway.' => 'ගාස්තු මතක් කිරීම්, අනතුරු ඇඟවීම් සහ සන්නිවේදනය සඳහා පද්ධතිය WhatsApp සමඟ ක්‍රියා කරන ආකාරය සකසන්න. web/desktop සබැඳි කෙලින්ම භාවිත කළ හැකිය, නැතහොත් WA Client API gateway එකක් සම්බන්ධ කළ හැකිය.',
    'Contact & Personal Information' => 'සම්බන්ධතා සහ පෞද්ගලික තොරතුරු',
    'Could not add the download.' => 'බාගත කිරීම එක් කළ නොහැකි විය.',
    'Could not reach the server. Try again.' => 'සේවාදායකයට සම්බන්ධ විය නොහැකි විය. නැවත උත්සාහ කරන්න.',
    'Could not save the email settings.' => 'විද්‍යුත් තැපැල් සැකසුම් සුරැකිය නොහැකි විය.',
    'Could not send by SMS. Check the SMS gateway in Settings, or use the manual option instead.' => 'SMS මගින් යැවිය නොහැකි විය. සැකසුම් තුළ SMS gateway එක පරීක්ෂා කරන්න, නැතහොත් අතින් යවන විකල්පය භාවිත කරන්න.',
    'Could not send by email. Email sending may not be set up on this server, or no "From" address is configured. Use the manual option instead.' => 'විද්‍යුත් තැපෑලෙන් යැවිය නොහැකි විය. මෙම සේවාදායකයේ විද්‍යුත් තැපැල් යැවීම සකසා නොතිබිය හැකිය, නැතහොත් යවන්නාගේ ලිපිනයක් සකසා නැත. ඒ වෙනුවට අතින් යවන විකල්පය භාවිත කරන්න.',
    'Could not update the download.' => 'බාගත කිරීම යාවත්කාලීන කළ නොහැකි විය.',
    'Default:' => 'පෙරනිමිය:',
    'Delete this slide? This cannot be undone.' => 'මෙම රූපය මකන්නද? මෙය පසුව හැරවිය නොහැක.',
    'Delete {title}? This cannot be undone.' => '{title} මකන්නද? මෙය පසුව හැරවිය නොහැක.',
    'Design the ad here' => 'දැන්වීම මෙතැනම නිර්මාණය කරන්න',
    'Display order on website' => 'වෙබ් අඩවියේ පෙන්වන අනුපිළිවෙල',
    'Download added.' => 'බාගත කිරීම එක් කරන ලදී.',
    'Download deleted.' => 'බාගත කිරීම මකන ලදී.',
    'Download updated.' => 'බාගත කිරීම යාවත්කාලීන කරන ලදී.',
    'Edit guardian' => 'භාරකරු සංස්කරණය කරන්න',
    'Email address' => 'විද්‍යුත් තැපැල් ලිපිනය',
    'Email sending is switched on.' => 'විද්‍යුත් තැපැල් යැවීම ක්‍රියාත්මකයි.',
    'Email settings saved.' => 'විද්‍යුත් තැපැල් සැකසුම් සුරකින ලදී.',
    'Email:' => 'විද්‍යුත් තැපෑල:',
    'Encoding for request body.' => 'ඉල්ලීමේ අන්තර්ගතය සඳහා කේතනය.',
    'Encryption' => 'සංකේතනය',
    'Enrolment for the new term is now open' => 'නව වාරය සඳහා ලියාපදිංචිය දැන් විවෘතයි',
    'Enter a valid "From" email address.' => 'වලංගු යවන්නාගේ විද්‍යුත් තැපැල් ලිපිනයක් ඇතුළත් කරන්න.',
    'Enter a valid SMTP port (1-65535).' => 'වලංගු SMTP port අංකයක් ඇතුළත් කරන්න (1-65535).',
    'Enter your test phone number.' => 'ඔබේ පරීක්ෂණ දුරකථන අංකය ඇතුළත් කරන්න.',
    'Everything that changes how the public website looks and what it says. Changes here do not affect the admin system.' => 'පොදු වෙබ් අඩවිය පෙනෙන ආකාරය සහ එහි අන්තර්ගතය වෙනස් කරන සියල්ල. මෙහි කරන වෙනස්කම් පරිපාලන පද්ධතියට බලපාන්නේ නැත.',
    'Fee not paid' => 'ගාස්තුව ගෙවා නැත',
    'Files are not uploaded here -- paste a Google Drive (or similar) share link.' => 'ලිපිගොනු මෙහි උඩුගත නොකෙරේ -- Google Drive (හෝ සමාන) බෙදාගැනීමේ සබැඳියක් අලවන්න.',
    'Fill in a "From" address and switch email on first.' => 'පළමුව යවන්නාගේ ලිපිනයක් පුරවා විද්‍යුත් තැපෑල ක්‍රියාත්මක කරන්න.',
    'Fill this in with a real mailbox\'s SMTP details and mail is sent through that account directly -- this is what makes email actually deliver, on this server or the live one. Leave the host blank to fall back to the server\'s own mail() instead.' => 'සැබෑ තැපැල් පෙට්ටියක SMTP විස්තර මෙහි පුරවන්න, එවිට තැපෑල එම ගිණුම හරහා කෙලින්ම යවනු ලැබේ -- මෙම සේවාදායකයේ හෝ සජීවී එකේ විද්‍යුත් තැපෑල ඇත්තටම ලැබෙන්නේ මෙය නිසයි. සත්කාරකය හිස්ව තැබුවහොත් සේවාදායකයේම mail() භාවිත වේ.',
    'Find out more' => 'වැඩි විස්තර',
    'Focus point' => 'අවධාන ලක්ෂ්‍යය',
    'Folder' => 'ෆෝල්ඩරය',
    'Folders' => 'ෆෝල්ඩර',
    'For Gmail, this needs to be a 16-character "App Password", not the normal account password (Google Account -> Security -> App passwords).' => 'Gmail සඳහා, මෙය අක්ෂර 16 ක "App Password" එකක් විය යුතුය, සාමාන්‍ය ගිණුමේ මුරපදය නොවේ (Google Account -> Security -> App passwords).',
    'Gateway API Endpoint URL' => 'Gateway API අන්ත ලක්ෂ්‍ය URL',
    'Gateway mode selected, but API endpoint URL is missing.' => 'Gateway ක්‍රමය තෝරා ඇත, නමුත් API අන්ත ලක්ෂ්‍ය URL නොමැත.',
    'Give items the same "Folder" name (e.g. "Grade 10 Papers") to group them into one folder on the public page -- leave it blank and the item sits under "Other files". Type a "/" to nest folders, e.g. "Grade 11/Science/1st Term" makes a Science sub-folder inside Grade 11, with a 1st Term sub-folder inside that -- name folders however you like, any depth.' => 'පොදු පිටුවේ එක් ෆෝල්ඩරයකට කාණ්ඩගත කිරීමට අයිතමවලට එකම "ෆෝල්ඩර" නම දෙන්න (උදා: "10 ශ්‍රේණියේ ප්‍රශ්න පත්‍ර") -- හිස්ව තැබුවහොත් අයිතමය "වෙනත් ලිපිගොනු" යටතේ තැබේ. ෆෝල්ඩර තුළ ෆෝල්ඩර සෑදීමට "/" ටයිප් කරන්න, උදා: "11 ශ්‍රේණිය/විද්‍යාව/1 වන වාරය" යනු 11 ශ්‍රේණිය තුළ විද්‍යාව උප ෆෝල්ඩරයක්, එය තුළ 1 වන වාරය උප ෆෝල්ඩරයක් -- කැමති පරිදි, කැමති ගැඹුරකට නම් කරන්න.',
    'Give the guardian\'s name and a Sri Lankan phone number (for example 0771234567).' => 'භාරකරුගේ නම සහ ශ්‍රී ලාංකික දුරකථන අංකයක් දෙන්න (උදා: 0771234567).',
    'Grades 6 to 11, at every branch. Ask at the office for a form.' => '6 සිට 11 දක්වා ශ්‍රේණි, සෑම ශාඛාවකම. පෝරමයක් සඳහා කාර්යාලයෙන් විමසන්න.',
    'Guardian added.' => 'භාරකරු එක් කරන ලදී.',
    'Guardian details updated.' => 'භාරකරුගේ විස්තර යාවත්කාලීන කරන ලදී.',
    'Guardian login deactivated. This does not affect the student or any other guardian.' => 'භාරකරුගේ පිවිසුම අක්‍රිය කරන ලදී. මෙය සිසුවාට හෝ වෙනත් භාරකරුවෙකුට බලපාන්නේ නැත.',
    'Guardian login reactivated.' => 'භාරකරුගේ පිවිසුම නැවත සක්‍රිය කරන ලදී.',
    'HTTP Method' => 'HTTP ක්‍රමය',
    'Hall' => 'ශාලාව',
    'Heading on the ad' => 'දැන්වීමේ ශීර්ෂය',
    'Hello from LMS! Test message from WhatsApp Client.' => 'පද්ධතියෙන් ආයුබෝවන්! WhatsApp Client එකෙන් පරීක්ෂණ පණිවිඩයකි.',
    'Hello {name}. Your class portal login: ID {id}, temporary password {password}. You must choose your own password the first time you log in.' => 'ආයුබෝවන් {name}. ඔබේ පන්ති ද්වාර පිවිසුම: අංකය {id}, තාවකාලික මුරපදය {password}. පළමු වරට පිවිසෙන විට ඔබේම මුරපදයක් තෝරාගත යුතුය.',
    'Homepage Background' => 'මුල් පිටුවේ පසුබිම',
    'How tall the branch photo/video banner shows on the public Classes page.' => 'පොදු පන්ති පිටුවේ ශාඛාවේ ඡායාරූප/වීඩියෝ පටියේ උස.',
    'How the site will look' => 'වෙබ් අඩවිය පෙනෙන ආකාරය',
    'If left blank, the general "Admin email" from Settings is used instead.' => 'හිස්ව තැබුවහොත්, සැකසුම් වල ඇති පොදු "පරිපාලක විද්‍යුත් තැපෑල" භාවිත වේ.',
    'In no class' => 'පන්තියක් නැත',
    'Instance / Session Name' => 'සැසියේ නම',
    'Institute Share (Rs.)' => 'ආයතනයේ කොටස (රු.)',
    'JPG, PNG or WEBP, up to 3MB. Shown on the public branches/classes pages.' => 'JPG, PNG හෝ WEBP, උපරිම 3MB. පොදු ශාඛා/පන්ති පිටු වල පෙන්වයි.',
    'JPG, PNG or WEBP, up to 3MB. Shown on the public branches/classes pages. Leave blank to keep the current photo.' => 'JPG, PNG හෝ WEBP, උපරිම 3MB. පොදු ශාඛා/පන්ති පිටු වල පෙන්වයි. දැනට ඇති ඡායාරූපය තබාගැනීමට හිස්ව තබන්න.',
    'JPG/PNG/WEBP photo (up to 3MB) or MP4/WEBM/MOV/OGG video (up to 35MB). The same one is used in both languages.' => 'JPG/PNG/WEBP ඡායාරූපයක් (උපරිම 3MB) හෝ MP4/WEBM/MOV/OGG වීඩියෝවක් (උපරිම 35MB). භාෂා දෙකේදීම එකම එක භාවිත වේ.',
    'Joined Date' => 'එක් වූ දිනය',
    'Key name for message body in payload (default: message).' => 'පණිවිඩයේ අන්තර්ගතය සඳහා යතුරේ නම (පෙරනිමිය: message).',
    'Key name for recipient number in payload (default: number).' => 'ලබන්නාගේ අංකය සඳහා යතුරේ නම (පෙරනිමිය: number).',
    'Large' => 'විශාල',
    'Late Count' => 'ප්‍රමාද වූ ගණන',
    'Leave a box blank to fall back to the default shown underneath it.' => 'කොටුවක් හිස්ව තැබුවහොත් ඊට පහළින් පෙන්වා ඇති පෙරනිමි අගය භාවිත වේ.',
    'Leave blank to keep the current file.' => 'දැනට ඇති ගොනුව තබාගැනීමට හිස්ව තබන්න.',
    'Leave blank to keep the saved password' => 'සුරකින ලද මුරපදය තබාගැනීමට හිස්ව තබන්න',
    'Leave this off to keep using phone/in-person and SMS only.' => 'දුරකථනය/සෘජු සම්බන්ධතාව සහ SMS පමණක් දිගටම භාවිත කිරීමට මෙය ක්‍රියාවිරහිතව තබන්න.',
    'Left blank, the title above is used.' => 'හිස්ව තැබුවහොත් ඉහත සිරස්තලය භාවිත වේ.',
    'Lets the office email a student or parent their login ID and temporary password, or a password-reset code, straight from the "Login details" screen.' => 'සිසුවෙකුට හෝ දෙමාපියෙකුට ඔවුන්ගේ පිවිසුම් අංකය සහ තාවකාලික මුරපදය, නැතහොත් මුරපද යළි පිහිටුවීමේ කේතය, "පිවිසුම් විස්තර" තිරයෙන්ම විද්‍යුත් තැපෑලෙන් යැවීමට කාර්යාලයට ඉඩ දෙයි.',
    'Lettering' => 'අකුරු',
    'Lower numbers show first on the public Classes page, the home page and the footer.' => 'කුඩා අංක පොදු පන්ති පිටුවේ, මුල් පිටුවේ සහ පාදයේ මුලින්ම පෙන්වයි.',
    'Lower numbers show first on the public Classes page, the home page and the footer. Branches with the same number fall back to the order they were added.' => 'කුඩා අංක පොදු පන්ති පිටුවේ, මුල් පිටුවේ සහ පාදයේ මුලින්ම පෙන්වයි. එකම අංකය ඇති ශාඛා එක් කළ අනුපිළිවෙලට පෙන්වයි.',
    'Manage' => 'කළමනාකරණය',
    'Medium (default)' => 'මධ්‍යම (පෙරනිමිය)',
    'Message Content' => 'පණිවිඩයේ අන්තර්ගතය',
    'Message Parameter Name' => 'පණිවිඩ පරාමිතියේ නම',
    'Messages are dispatched directly to your WhatsApp client.' => 'පණිවිඩ ඔබේ WhatsApp සේවාදායකයට කෙලින්ම යවනු ලැබේ.',
    'Missing details. Reload the page and try again.' => 'විස්තර අසම්පූර්ණයි. පිටුව නැවත පූරණය කර උත්සාහ කරන්න.',
    'Most REST WA clients use POST.' => 'බොහෝ REST WA සේවාදායක POST භාවිත කරයි.',
    'Move' => 'ගෙනයන්න',
    'No email address on file' => 'ගොනුවේ විද්‍යුත් තැපැල් ලිපිනයක් නැත',
    'No phone number on file' => 'ගොනුවේ දුරකථන අංකයක් නැත',
    'No phone number on file for this person.' => 'මෙම පුද්ගලයා සඳහා ගොනුවේ දුරකථන අංකයක් නැත.',
    'No picture needed -- pick a look, type the words, choose the colours.' => 'ඡායාරූපයක් අවශ්‍ය නැත -- පෙනුමක් තෝරා, වචන ටයිප් කර, වර්ණ තෝරන්න.',
    'No text matched that search.' => 'එම සෙවීමට ගැළපෙන පෙළක් නැත.',
    'No valid email address on file for this person.' => 'මෙම පුද්ගලයා සඳහා ගොනුවේ වලංගු විද්‍යුත් තැපැල් ලිපිනයක් නැත.',
    'None' => 'කිසිවක් නැත',
    'Not saved yet -- press Save changes to put this on the site.' => 'තවම සුරකා නැත -- මෙය වෙබ් අඩවියට දැමීමට "වෙනස්කම් සුරකින්න" ඔබන්න.',
    'Not set up yet.' => 'තවම සකසා නැත.',
    'Noted, continue scanning' => 'සටහන් කරගත්තා, ස්කෑන් කිරීම දිගටම කරන්න',
    'Optional. Shown under the branch photo on the public website.' => 'අත්‍යවශ්‍ය නැත. පොදු වෙබ් අඩවියේ ශාඛාවේ ඡායාරූපයට පහළින් පෙන්වයි.',
    'Order: {n}' => 'අනුපිළිවෙල: {n}',
    'Passed as Authorization Bearer header or {key} placeholder.' => 'Authorization Bearer header ලෙස හෝ {key} ස්ථානධාරකය ලෙස යවනු ලැබේ.',
    'Past papers, notes and other files shared on the public Downloads page, arranged into folders.' => 'පොදු බාගත කිරීම් පිටුවේ බෙදාගන්නා පසුගිය ප්‍රශ්න පත්‍ර, සටහන් සහ වෙනත් ලිපිගොනු, ෆෝල්ඩර වලට සකසා ඇත.',
    'Payload Format' => 'දත්ත ආකෘතිය',
    'Pending (Rs.)' => 'ගෙවීමට ඇති (රු.)',
    'Phone (login number)' => 'දුරකථනය (පිවිසුම් අංකය)',
    'Phone 1' => 'දුරකථනය 1',
    'Phone Parameter Name' => 'දුරකථන පරාමිතියේ නම',
    'Photo' => 'ඡායාරූපය',
    'Photo or video' => 'ඡායාරූපයක් හෝ වීඩියෝවක්',
    'Photo/video banner size (Classes page)' => 'ඡායාරූප/වීඩියෝ පටියේ ප්‍රමාණය (පන්ති පිටුව)',
    'Photo: JPG/PNG/WEBP up to 5MB. Video: MP4/WEBM/MOV/OGG up to 35MB.' => 'ඡායාරූපය: JPG/PNG/WEBP උපරිම 5MB. වීඩියෝව: MP4/WEBM/MOV/OGG උපරිම 35MB.',
    'Pick one of the ten styles, press Save changes, then open the site in another tab to see it. Nothing goes live until you save, so you can click through the styles freely.' => 'මෝස්තර දහයෙන් එකක් තෝරා, "වෙනස්කම් සුරකින්න" ඔබා, වෙබ් අඩවිය බලන්න. සුරකින තුරු කිසිවක් සජීවී නොවේ, එබැවින් නිදහසේ මෝස්තර බලන්න.',
    'Port' => 'Port අංකය',
    'Present Count' => 'පැමිණි ගණන',
    'Preview on the site' => 'වෙබ් අඩවියේ පෙරදසුන',
    'Public' => 'පොදු',
    'Put the colours, motion and show/hide switches back to how the site started? Your wording and photos are not touched.' => 'වර්ණ, චලනය සහ පෙන්වීම/සැඟවීමේ ස්විච ආරම්භයේ තිබූ ආකාරයට ගෙන යන්නද? ඔබේ වචන සහ ඡායාරූප වෙනස් නොවේ.',
    'Put the look back to how it started' => 'පෙනුම ආරම්භයේ තිබූ ආකාරයට ගෙන යන්න',
    'Ready-made styles' => 'සූදානම් මෝස්තර',
    'Recipient Phone Number' => 'ලබන්නාගේ දුරකථන අංකය',
    'Rejected.' => 'ප්‍රතික්ෂේප කරන ලදී.',
    'Remove this and use the original instead' => 'මෙය ඉවත් කර මුල් එක භාවිත කරන්න',
    'Replace photo/video (optional)' => 'ඡායාරූපය/වීඩියෝව වෙනුවට අලුත් එකක් (අත්‍යවශ්‍ය නැත)',
    'Required by some multi-session WA clients.' => 'සමහර බහු-සැසි WA සේවාදායක සඳහා අවශ්‍ය වේ.',
    'Resend by email' => 'විද්‍යුත් තැපෑලෙන් නැවත යවන්න',
    'SMTP (recommended)' => 'SMTP (නිර්දේශිතයි)',
    'SMTP host' => 'SMTP සත්කාරකය',
    'SMTP password' => 'SMTP මුරපදය',
    'SMTP username' => 'SMTP පරිශීලක නාමය',
    'SSL (465)' => 'SSL (465)',
    'STARTTLS (587)' => 'STARTTLS (587)',
    'Save a "From" address and switch email on first.' => 'පළමුව යවන්නාගේ ලිපිනයක් සුරකා විද්‍යුත් තැපෑල ක්‍රියාත්මක කරන්න.',
    'Saved. Leave empty to keep existing key.' => 'සුරකින ලදී. දැනට ඇති යතුර තබාගැනීමට හිස්ව තබන්න.',
    'Search text...' => 'පෙළ සොයන්න...',
    'Second Phone' => 'දෙවන දුරකථනය',
    'Second line' => 'දෙවන පේළිය',
    'Select how staff and automated notifications should interact with WhatsApp.' => 'කාර්ය මණ්ඩලය සහ ස්වයංක්‍රීය දැනුම්දීම් WhatsApp සමඟ ක්‍රියා කළ යුතු ආකාරය තෝරන්න.',
    'Send Test Message' => 'පරීක්ෂණ පණිවිඩයක් යවන්න',
    'Send a test email' => 'පරීක්ෂණ විද්‍යුත් තැපෑලක් යවන්න',
    'Send a test message to verify that your WA Client or WhatsApp configuration works properly.' => 'ඔබේ WA Client හෝ WhatsApp සැකසුම නිවැරදිව ක්‍රියා කරනවාද යන්න තහවුරු කිරීමට පරීක්ෂණ පණිවිඩයක් යවන්න.',
    'Send by SMS' => 'SMS මගින් යවන්න',
    'Send by WhatsApp' => 'WhatsApp මගින් යවන්න',
    'Send by email' => 'විද්‍යුත් තැපෑලෙන් යවන්න',
    'Send one email to prove this server can actually deliver, before a parent has to rely on it. A local development server usually has no mail transport configured, so this is expected to fail here.' => 'දෙමාපියෙකුට මෙය මත රඳා සිටීමට සිදුවීමට පෙර, මෙම සේවාදායකයට ඇත්තටම යැවිය හැකිද යන්න තහවුරු කිරීමට එක් විද්‍යුත් තැපෑලක් යවන්න. දේශීය සංවර්ධන සේවාදායකයක සාමාන්‍යයෙන් තැපැල් සේවාවක් සකසා නැත, එබැවින් මෙය මෙහිදී අසාර්ථක වීම අපේක්ෂිතයි.',
    'Send test email' => 'පරීක්ෂණ විද්‍යුත් තැපෑල යවන්න',
    'Send to' => 'යවන්නේ',
    'Sending Mode' => 'යැවීමේ ක්‍රමය',
    'Sending...' => 'යවමින්...',
    'Sent by SMS.' => 'SMS මගින් යවන ලදී.',
    'Sent by email.' => 'විද්‍යුත් තැපෑලෙන් යවන ලදී.',
    'Short public description' => 'කෙටි පොදු විස්තරය',
    'Show or hide' => 'පෙන්වන්න හෝ සඟවන්න',
    'Show or hide this line on the website. Hiding keeps the wording here.' => 'මෙම පේළිය වෙබ් අඩවියේ පෙන්වන්න හෝ සඟවන්න. සැඟවූවත් වචන මෙහි තිබේ.',
    'Showing a preview. Nothing has been saved yet.' => 'පෙරදසුනක් පෙන්වමින්. තවම කිසිවක් සුරකා නැත.',
    'Shown' => 'පෙන්වයි',
    'Shown only once. Give these details to the person directly -- in person, by calling the phone number already on file, or using the Send buttons below. Do not forward them to anyone else, and do not keep a copy.' => 'එක් වරක් පමණක් පෙන්වයි. මෙම විස්තර එම පුද්ගලයාට කෙලින්ම දෙන්න -- සෘජුවම, ගොනුවේ ඇති දුරකථන අංකයට කතා කර, නැතහොත් පහත යැවීමේ බොත්තම් භාවිත කර. වෙන කිසිවෙකුට මේවා යොමු නොකරන්න, පිටපතක්ද තබා නොගන්න.',
    'Shows the real pages with what is on this form, without saving. A bar at the top brings you back here.' => 'මෙම පෝරමයේ ඇති දේ සමඟ සැබෑ පිටු පෙන්වයි, සුරකින්නේ නැතිව. ඉහළ ඇති පටියෙන් නැවත මෙහි එන්න පුළුවන්.',
    'Sinhala and English wording across the site, including anything you have written yourself.' => 'ඔබම ලියූ ඕනෑම දෙයක් ඇතුළුව, මුළු වෙබ් අඩවියේම සිංහල සහ ඉංග්‍රීසි වචන.',
    'Small' => 'කුඩා',
    'Staff, site-wide' => 'කාර්ය මණ්ඩලය, මුළු අඩවියම',
    'Standard wa.me click-to-chat links are active.' => 'සම්මත wa.me click-to-chat සබැඳි ක්‍රියාත්මකයි.',
    'Start with Design & content.' => 'මෝස්තරය සහ අන්තර්ගතය සමඟ පටන් ගන්න.',
    'Student Status & Deactivation Reports' => 'සිසු තත්ත්වය සහ අක්‍රිය කිරීමේ වාර්තා',
    'Students Count' => 'සිසුන් ගණන',
    'Styles' => 'මෝස්තර',
    'Teacher Share (Rs.)' => 'ගුරුවරයාගේ කොටස (රු.)',
    'Ten ready-made styles, your own colours, the menu bar, lettering, corner roundness, and every piece of wording on the public pages.' => 'සූදානම් මෝස්තර දහයක්, ඔබේම වර්ණ, මෙනු තීරුව, අකුරු, කොන් වක්‍රතාව, සහ පොදු පිටු වල සෑම වචනයක්ම.',
    'Test WhatsApp Client Sending' => 'WhatsApp Client යැවීම පරීක්ෂා කරන්න',
    'Test email from the class portal' => 'පන්ති ද්වාරයෙන් පරීක්ෂණ විද්‍යුත් තැපෑලක්',
    'Test email handed to the server. Check the inbox (and spam folder).' => 'පරීක්ෂණ විද්‍යුත් තැපෑල සේවාදායකයට භාර දෙන ලදී. එන ලිපි (සහ spam ෆෝල්ඩරය) පරීක්ෂා කරන්න.',
    'Test message sent via WA Client! Check the recipient phone.' => 'WA Client හරහා පරීක්ෂණ පණිවිඩය යවන ලදී! ලබන්නාගේ දුරකථනය පරීක්ෂා කරන්න.',
    'That text could not be found.' => 'එම පෙළ සොයාගත නොහැකි විය.',
    'The "Send by email" button will not work until this is switched on and a "From" address is set.' => 'මෙය ක්‍රියාත්මක කර යවන්නාගේ ලිපිනයක් සකසන තුරු "විද්‍යුත් තැපෑලෙන් යවන්න" බොත්තම ක්‍රියා නොකරයි.',
    'The button uses the link above. With no link it shows as a plain label.' => 'බොත්තම ඉහත සබැඳිය භාවිත කරයි. සබැඳියක් නැතිනම් එය සාමාන්‍ය ලේබලයක් ලෙස පෙන්වයි.',
    'The email could not be sent. If no SMTP host is filled in above, add one (Gmail, the domain\'s own mailbox, etc.) -- a local XAMPP install has no mail server of its own, so plain mail() will not work here.' => 'විද්‍යුත් තැපෑල යැවිය නොහැකි විය. ඉහත SMTP සත්කාරකයක් පුරවා නොමැති නම් එකක් එක් කරන්න (Gmail, වසමේම තැපැල් පෙට්ටිය, ආදිය) -- දේශීය XAMPP ස්ථාපනයකට තමන්ගේම තැපැල් සේවාදායකයක් නැත, එබැවින් සාමාන්‍ය mail() මෙහි ක්‍රියා නොකරයි.',
    'The full HTTP/HTTPS endpoint URL where requests will be sent.' => 'ඉල්ලීම් යවනු ලබන සම්පූර්ණ HTTP/HTTPS අන්ත ලක්ෂ්‍ය URL.',
    'The look' => 'පෙනුම',
    'The look could not be reset. Please try again.' => 'පෙනුම යළි පිහිටුවිය නොහැකි විය. කරුණාකර නැවත උත්සාහ කරන්න.',
    'The look has been put back to how the site started. Your wording and photos were not touched.' => 'පෙනුම වෙබ් අඩවිය ආරම්භයේ තිබූ ආකාරයට ගෙන යන ලදී. ඔබේ වචන සහ ඡායාරූප වෙනස් කර නැත.',
    'The photos and short videos behind the heading on the home page. Add as many as you like and set the order.' => 'මුල් පිටුවේ ශීර්ෂයට පිටුපසින් ඇති ඡායාරූප සහ කෙටි වීඩියෝ. කැමති තරම් එක් කර අනුපිළිවෙල සකසන්න.',
    'The photos or short videos that crossfade behind the heading on the public home page. Add as many as you like; they play in the order below. Leave this empty to keep the original fixed photos.' => 'පොදු මුල් පිටුවේ ශීර්ෂයට පිටුපසින් මාරුවෙන මාරුවට පෙන්වන ඡායාරූප හෝ කෙටි වීඩියෝ. කැමති තරම් එක් කරන්න; ඒවා පහත අනුපිළිවෙලට පෙන්වයි. මුල් ස්ථිර ඡායාරූප තබාගැනීමට මෙය හිස්ව තබන්න.',
    'The second phone number is not a valid Sri Lankan number.' => 'දෙවන දුරකථන අංකය වලංගු ශ්‍රී ලාංකික අංකයක් නොවේ.',
    'The strip at the top of the home page, for a seminar, a notice or an offer.' => 'මුල් පිටුවේ ඉහළ ඇති පටිය -- සම්මන්ත්‍රණයක්, දැනුම්දීමක් හෝ විශේෂ දීමනාවක් සඳහා.',
    'The student has been checked in. Please mention this at the desk.' => 'සිසුවා පැමිණි බව සටහන් කර ඇත. කරුණාකර මෙය කවුන්ටරයේදී සඳහන් කරන්න.',
    'The test text to dispatch.' => 'යැවීමට ඇති පරීක්ෂණ පෙළ.',
    'This is a test email from the class portal. If you can read this, email sending is working.' => 'මෙය පන්ති ද්වාරයෙන් එවන පරීක්ෂණ විද්‍යුත් තැපෑලකි. ඔබට මෙය කියවිය හැකි නම්, විද්‍යුත් තැපැල් යැවීම ක්‍රියාත්මකයි.',
    'This is exactly how it will look on the site' => 'වෙබ් අඩවියේ එය පෙනෙන්නේ හරියටම මෙලෙසයි',
    'This is what is saved now.' => 'දැන් සුරකා ඇත්තේ මෙයයි.',
    'This phone number is already a parent login for another child. The parent portal shows one child per phone number, so use a different number if this guardian needs to see this child too.' => 'මෙම දුරකථන අංකය දැනටමත් තවත් දරුවෙකුගේ දෙමාපිය පිවිසුමකි. දෙමාපිය ද්වාරය දුරකථන අංකයකට එක් දරුවෙකු පෙන්වයි, එබැවින් මෙම භාරකරුට මෙම දරුවාද බැලීමට අවශ්‍ය නම් වෙනත් අංකයක් භාවිත කරන්න.',
    'This phone number is already a parent login for another child. The parent portal shows one child per phone number.' => 'මෙම දුරකථන අංකය දැනටමත් තවත් දරුවෙකුගේ දෙමාපිය පිවිසුමකි. දෙමාපිය ද්වාරය දුරකථන අංකයකට එක් දරුවෙකු පෙන්වයි.',
    'This student is registered but not in any running class, so their portal is empty. Click to enrol them.' => 'මෙම සිසුවා ලියාපදිංචි වී ඇතත් ක්‍රියාත්මක පන්තියක නැත, එබැවින් ඔවුන්ගේ ද්වාරය හිස්ය. ලියාපදිංචි කිරීමට ක්ලික් කරන්න.',
    'Translation updated.' => 'පරිවර්තනය යාවත්කාලීන කරන ලදී.',
    'Tried a few and want to start over?' => 'කිහිපයක් උත්සාහ කර නැවත පටන් ගන්න ඕනෑද?',
    'Two ways: fill the enrol form yourself (pick a branch and class, upload your bank deposit slip) and the branch office approves it, or send an inquiry and the office will call you back. Either way you get a student ID and password for the portal.' => 'ක්‍රම දෙකක්: ඔබම ලියාපදිංචි පෝරමය පුරවන්න (ශාඛාවක් සහ පන්තියක් තෝරා, බැංකු තැන්පතු පත්‍රිකාව උඩුගත කරන්න), ශාඛා කාර්යාලය එය අනුමත කරයි; නැතහොත් විමසීමක් එවන්න, කාර්යාලයෙන් ඔබට ආපසු කතා කරනු ලැබේ. කුමන ක්‍රමයෙන් වුවද ඔබට ද්වාරය සඳහා සිසු අංකයක් සහ මුරපදයක් ලැබේ.',
    'Unpaid months' => 'ගෙවා නැති මාස',
    'User & Staff Directory Reports' => 'පරිශීලක සහ කාර්ය මණ්ඩල නාමාවලි වාර්තා',
    'User & Staff Reports' => 'පරිශීලක සහ කාර්ය මණ්ඩල වාර්තා',
