    'WhatsApp Web Direct mode is active.' => 'WhatsApp Web සෘජු ක්‍රමය ක්‍රියාත්මකයි.',
    'WhatsApp settings saved successfully.' => 'WhatsApp සැකසුම් සාර්ථකව සුරකින ලදී.',
    'Your class portal login details' => 'ඔබේ පන්ති ද්වාර පිවිසුම් විස්තර',
    'e.g. Find out more' => 'උදා: වැඩි විස්තර',
    'e.g. Grade 10 Papers, or Grade 11/Science/1st Term' => 'උදා: 10 ශ්‍රේණියේ ප්‍රශ්න පත්‍ර, හෝ 11 ශ්‍රේණිය/විද්‍යාව/1 වන වාරය',
    'e.g. Grade 10 term test papers' => 'උදා: 10 ශ්‍රේණියේ වාර විභාග ප්‍රශ්න පත්‍ර',
    'e.g. Science classes for Grades 6-11, physical and online.' => 'උදා: 6-11 ශ්‍රේණි සඳහා විද්‍යා පන්ති, භෞතිකව සහ මාර්ගගතව.',
    'for' => 'සඳහා',
    '{n} in use' => 'භාවිතයේ {n}',
    '{n} matching results' => 'ගැළපෙන ප්‍රතිඵල {n}',

    // ---- CMS field labels, group headings and style names --------------
    // These reach the screen through te() but are written as array
    // values in SiteContentService, not as t() literals, so a scan for
