    '"In class" paragraph' => '"පන්තියේදී" ඡේදය',
    '% (lower is fainter)' => '% (අඩු නම් වඩා මැකී පෙනේ)',
    '% of the normal size' => '% සාමාන්‍ය ප්‍රමාණයෙන්',
    '-- its heading' => '-- එහි ශීර්ෂය',
    '-- its wording' => '-- එහි වචන',
    '100% is the tint the site ships with. Lower it to let more of the photo through; 0% removes it. Keep enough tint that the white heading stays readable.' => 'වෙබ් අඩවිය සමඟ එන වර්ණ ආලේපය 100% කි. ඡායාරූපය වැඩියෙන් පෙනෙන්නට අඩු කරන්න; 0% කළොත් එය ඉවත් වේ. සුදු ශීර්ෂය කියවිය හැකිව තබාගන්නට ප්‍රමාණවත් ආලේපයක් තබන්න.',
    'A bigger number drifts more slowly.' => 'අංකය වැඩි වන තරමට සෙමින් ගමන් කරයි.',
    'About page: "In class" section photo' => 'අප ගැන පිටුව: "පන්තියේදී" කොටසේ ඡායාරූපය',
    'Answer 1' => 'පිළිතුර 1',
    'Answer 2' => 'පිළිතුර 2',
    'Answer 3' => 'පිළිතුර 3',
    'Answer 4' => 'පිළිතුර 4',
