    'Background photos: how long each one is shown' => 'පසුබිම් ඡායාරූප: එකක් පෙන්වන කාලය',
    'Blue-green, modern and clean.' => 'නිල්-කොළ, නවීන සහ පිරිසිදු.',
    'Branches: heading' => 'ශාඛා: ශීර්ෂය',
    'Branches: intro line' => 'ශාඛා: හැඳින්වීමේ පේළිය',
    'Classes page' => 'පන්ති පිටුව',
    'Classes teaser: heading' => 'පන්ති පෙරදසුන: ශීර්ෂය',
    'Classes teaser: intro line' => 'පන්ති පෙරදසුන: හැඳින්වීමේ පේළිය',
    'Classic, a prize-giving feel.' => 'සම්භාව්‍ය, ත්‍යාග ප්‍රදානෝත්සවයක හැඟීමක්.',
    'Colour tint over the background photo' => 'පසුබිම් ඡායාරූපය මත වර්ණ ආලේපය',
    'Corner roundness' => 'කොන් වක්‍රතාව',
    'Crimson' => 'තද රතු',
    'Deep navy, calm and formal.' => 'තද නිල්, සන්සුන් සහ විධිමත්.',
    'Downloads page' => 'බාගත කිරීම් පිටුව',
    'Downloads page: show how many files each folder holds' => 'බාගත කිරීම් පිටුව: එක් ෆෝල්ඩරයක ඇති ලිපිගොනු ගණන පෙන්වන්න',
    'Downloads page: which folders start open' => 'බාගත කිරීම් පිටුව: ආරම්භයේදී විවෘතව තිබිය යුතු ෆෝල්ඩර',
    'Drifting icons: how faint they are' => 'ගමන් කරන අයිකන: ඒවා කෙතරම් මැකී පෙනේද',
    'Drifting icons: how long one full drift takes' => 'ගමන් කරන අයිකන: එක් සම්පූර්ණ ගමනකට ගතවන කාලය',
    'Drifting icons: size' => 'ගමන් කරන අයිකන: ප්‍රමාණය',
    'Emerald' => 'මරකත',
    'Events page' => 'අවස්ථා පිටුව',
    'Extra paragraph (optional -- leave blank to hide)' => 'අමතර ඡේදය (අත්‍යවශ්‍ය නැත -- සැඟවීමට හිස්ව තබන්න)',
    'Fresh green, easy on the eye.' => 'නැවුම් කොළ, ඇසට පහසුයි.',
