    'Graphite' => 'අළු',
    'Grey and quiet; photos stand out.' => 'අළු සහ නිහඬ; ඡායාරූප කැපී පෙනේ.',
    'Heading' => 'ශීර්ෂය',
    'Heading beside the form' => 'පෝරමය අසල ශීර්ෂය',
    'Hero paragraph (under the heading)' => 'ප්‍රධාන ඡේදය (ශීර්ෂයට පහළින්)',
    'Hero: first button' => 'ප්‍රධාන කොටස: පළමු බොත්තම',
    'Hero: second button' => 'ප්‍රධාන කොටස: දෙවන බොත්තම',
    'Highlight colour (buttons that must stand out)' => 'කැපී පෙනෙන වර්ණය (වැදගත් බොත්තම් සඳහා)',
    'Home page background: photos, tint and motion' => 'මුල් පිටුවේ පසුබිම: ඡායාරූප, වර්ණ ආලේපය සහ චලනය',
    'Home page: show "How the classes work"' => 'මුල් පිටුව: "පන්ති ක්‍රියාත්මක වන ආකාරය" පෙන්වන්න',
    'Home page: show the upcoming seminar strip at the top' => 'මුල් පිටුව: ඉහළ ඇති ඉදිරි සම්මන්ත්‍රණ පටිය පෙන්වන්න',
    'Home page: show the wording over the background photo' => 'මුල් පිටුව: පසුබිම් ඡායාරූපය මත ඇති වචන පෙන්වන්න',
    'Intro line (under the heading)' => 'හැඳින්වීමේ පේළිය (ශීර්ෂයට පහළින්)',
    'Line under that heading' => 'එම ශීර්ෂයට පහළ පේළිය',
    'Main colour (buttons, links, highlights)' => 'ප්‍රධාන වර්ණය (බොත්තම්, සබැඳි, කැපී පෙනෙන දේ)',
    'Menu: show "Downloads"' => 'මෙනුව: "බාගත කිරීම්" පෙන්වන්න',
    'Menu: show "Events"' => 'මෙනුව: "අවස්ථා" පෙන්වන්න',
    'Menu: show a Facebook button (uses the Facebook address on the Contact tab)' => 'මෙනුව: Facebook බොත්තමක් පෙන්වන්න (සම්බන්ධතා ටැබයේ ඇති Facebook ලිපිනය භාවිත කරයි)',
    'Menu: show the "Enrol now" button' => 'මෙනුව: "දැන් ලියාපදිංචි වන්න" බොත්තම පෙන්වන්න',
    'Menu: show the "Login" button' => 'මෙනුව: "පිවිසෙන්න" බොත්තම පෙන්වන්න',
    'Midnight' => 'මධ්‍යම රාත්‍රිය',
    'Ocean' => 'සාගරය',
    'Off keeps the admin dashboard in its standard blue, which many offices prefer so staff can tell the two apart at a glance.' => 'ක්‍රියාවිරහිත කළහොත් පරිපාලන උපකරණ පුවරුව එහි සම්මත නිල් පාටින්ම පවතී. කාර්ය මණ්ඩලයට දෙක වෙන්කර හඳුනාගැනීමට පහසු නිසා බොහෝ කාර්යාල මෙයට කැමතියි.',
    'Only ever shown when at least one class is actually marked as online, so this cannot advertise something the institute does not run.' => 'අවම වශයෙන් එක් පන්තියක්වත් මාර්ගගත ලෙස සලකුණු කර ඇති විට පමණක් පෙන්වයි, එබැවින් ආයතනය නොකරන දෙයක් මෙයින් ප්‍රචාරය කළ නොහැක.',
    'Only ever shown when branches have actually been added, so this cannot produce an empty list.' => 'ශාඛා එක් කර ඇති විට පමණක් පෙන්වයි, එබැවින් මෙයින් හිස් ලැයිස්තුවක් ඇති නොවේ.',
    'Only matters when more than one background photo is active.' => 'පසුබිම් ඡායාරූප එකකට වඩා ක්‍රියාත්මක විට පමණක් වැදගත් වේ.',
    'Opening animation: how long it stays on screen' => 'ආරම්භක සජීවිකරණය: තිරයේ රැඳෙන කාලය',
    'Orange, bright and friendly.' => 'තැඹිලි, දීප්තිමත් සහ මිත්‍රශීලී.',
    'Page background colour' => 'පිටුවේ පසුබිම් වර්ණය',
    'Paragraph about the teacher' => 'ගුරුවරයා ගැන ඡේදය',
    'Plum' => 'දම්',
    'Purple, distinctive and warm.' => 'දම්, සුවිශේෂී සහ උණුසුම්.',
    'Question 1' => 'ප්‍රශ්නය 1',
    'Question 2' => 'ප්‍රශ්නය 2',
    'Question 3' => 'ප්‍රශ්නය 3',
    'Question 4' => 'ප්‍රශ්නය 4',
    'Question 5 (leave blank to hide)' => 'ප්‍රශ්නය 5 (සැඟවීමට හිස්ව තබන්න)',
    'Raise this to let people read it; lower it to get to the page sooner.' => 'කියවීමට කාලය දීමට මෙය වැඩි කරන්න; පිටුවට ඉක්මනින් යාමට අඩු කරන්න.',
    'Royal Blue' => 'රාජකීය නිල්',
    'Second colour (gradients and accents)' => 'දෙවන වර්ණය (වර්ණ මාරුවීම් සහ විශේෂිත කොටස්)',
    'Section heading' => 'කොටසේ ශීර්ෂය',
