    'Show or hide parts of the site' => 'වෙබ් අඩවියේ කොටස් පෙන්වන්න හෝ සඟවන්න',
    'Show step 1' => '1 වන පියවර පෙන්වන්න',
    'Show step 2' => '2 වන පියවර පෙන්වන්න',
    'Show step 3' => '3 වන පියවර පෙන්වන්න',
    'Show step 4' => '4 වන පියවර පෙන්වන්න',
    'Show the "Absence alerts" card' => '"නොපැමිණීම් දැනුම්දීම්" කාඩ්පත පෙන්වන්න',
    'Show the "Find us online" section' => '"අපව මාර්ගගතව සොයන්න" කොටස පෙන්වන්න',
    'Show the "In class" section' => '"පන්තියේදී" කොටස පෙන්වන්න',
    'Show the "Online classes" card' => '"මාර්ගගත පන්ති" කාඩ්පත පෙන්වන්න',
    'Show the "Parent portal" card' => '"දෙමාපිය ද්වාරය" කාඩ්පත පෙන්වන්න',
    'Show the "Past papers" card' => '"පසුගිය ප්‍රශ්න පත්‍ර" කාඩ්පත පෙන්වන්න',
    'Show the "Quizzes and homework" card' => '"ප්‍රශ්නාවලි සහ ගෙදර වැඩ" කාඩ්පත පෙන්වන්න',
    'Show the "Recordings and notes" card' => '"පටිගත කිරීම් සහ සටහන්" කාඩ්පත පෙන්වන්න',
    'Show the "Send a message" form' => '"පණිවිඩයක් යවන්න" පෝරමය පෙන්වන්න',
    'Show the "Sinhala or English" card' => '"සිංහල හෝ ඉංග්‍රීසි" කාඩ්පත පෙන්වන්න',
    'Show the "Weekly classes" card' => '"සතිපතා පන්ති" කාඩ්පත පෙන්වන්න',
    'Show the "Would you like your child to join?" panel at the end' => 'අවසානයේ ඇති "ඔබේ දරුවා එක් කරගන්නද?" පැනලය පෙන්වන්න',
    'Show the branch list' => 'ශාඛා ලැයිස්තුව පෙන්වන්න',
    'Show the drifting science icons over the background' => 'පසුබිම මත ගමන් කරන විද්‍යා අයිකන පෙන්වන්න',
    'Show the opening animation when the site is first opened' => 'වෙබ් අඩවිය පළමුවරට විවෘත කරන විට ආරම්භක සජීවිකරණය පෙන්වන්න',
    'Show the teacher section' => 'ගුරුවරයාගේ කොටස පෙන්වන්න',
    'Shown when no branch is published yet' => 'තවම ශාඛාවක් ප්‍රකාශ කර නොමැති විට පෙන්වයි',
    'Shown when no event is published yet' => 'තවම අවස්ථාවක් ප්‍රකාශ කර නොමැති විට පෙන්වයි',
    'Shown when nothing has been shared yet' => 'තවම කිසිවක් බෙදාගෙන නොමැති විට පෙන්වයි',
    'Site design: themes, colours and the menu bar' => 'වෙබ් අඩවියේ මෝස්තරය: තේමා, වර්ණ සහ මෙනු තීරුව',
    'Small label above the heading' => 'ශීර්ෂයට ඉහළින් කුඩා ලේබලය',
    'Small label above the teacher\'s name' => 'ගුරුවරයාගේ නමට ඉහළින් කුඩා ලේබලය',
    'Soft sky blue, light and airy.' => 'මෘදු අහස් නිල්, සැහැල්ලු සහ නිදහස්.',
    'Step 1 heading' => '1 වන පියවරේ ශීර්ෂය',
    'Step 1 text' => '1 වන පියවරේ පෙළ',
