    'Step 4 text' => '4 වන පියවරේ පෙළ',
    'Strong red, high energy.' => 'තද රතු, ඉහළ ශක්තියක්.',
    'Students and parents can still reach the login page directly; this only hides the button.' => 'සිසුන්ට සහ දෙමාපියන්ට තවමත් පිවිසුම් පිටුවට කෙලින්ම යා හැකිය; මෙයින් සැඟවෙන්නේ බොත්තම පමණි.',
    'Sunset' => 'හිරු බැසීම',
    'Teacher photo or short video (home page hero and "Your teacher" section on the About page)' => 'ගුරුවරයාගේ ඡායාරූපය හෝ කෙටි වීඩියෝව (මුල් පිටුවේ ප්‍රධාන කොටස සහ අප ගැන පිටුවේ "ඔබේ ගුරුවරයා" කොටස)',
    'Teacher\'s name (overrides the name worked out from classes/branches below -- set this so the teacher photo and "Your teacher" section show even before any class has a teacher assigned)' => 'ගුරුවරයාගේ නම (පහත පන්ති/ශාඛා වලින් ගණනය කරන නමට වඩා මෙය ප්‍රමුඛ වේ -- කිසිම පන්තියකට ගුරුවරයෙකු පවරා නොමැති වුවද ගුරුවරයාගේ ඡායාරූපය සහ "ඔබේ ගුරුවරයා" කොටස පෙන්වීමට මෙය සකසන්න)',
    'Teal' => 'තද නිල්-කොළ',
    'The look the site ships with.' => 'වෙබ් අඩවිය සමඟ එන මුල් පෙනුම.',
    'Tick 1' => 'ලකුණ 1',
    'Tick 2' => 'ලකුණ 2',
    'Tick 3' => 'ලකුණ 3',
    'Tick 4' => 'ලකුණ 4',
    'Tick the ones you want. They are placed and timed automatically, so any number works -- four or five looks best.' => 'ඔබට අවශ්‍ය ඒවා තෝරන්න. ඒවා ස්වයංක්‍රීයව තැන්පත් කර කාලය සකසනු ලැබේ, එබැවින් ඕනෑම ගණනක් ගැළපේ -- හතරක් හෝ පහක් වඩාත් ලස්සනයි.',
    'Top menu bar: background colour' => 'ඉහළ මෙනු තීරුව: පසුබිම් වර්ණය',
    'Top menu bar: how it looks' => 'ඉහළ මෙනු තීරුව: එහි පෙනුම',
    'Top menu bar: text colour' => 'ඉහළ මෙනු තීරුව: අකුරු වර්ණය',
    'Turn this off if the office would rather families phoned or used WhatsApp.' => 'පවුල් දුරකථනයෙන් හෝ WhatsApp මගින් සම්බන්ධ වනවාට කාර්යාලය කැමති නම් මෙය ක්‍රියාවිරහිත කරන්න.',
    'Use these colours inside the admin system as well' => 'පරිපාලන පද්ධතිය තුළද මෙම වර්ණ භාවිත කරන්න',
    'Which icons drift over the background' => 'පසුබිම මත ගමන් කරන්නේ කුමන අයිකනද',
    'With only a few folders, opening all of them saves a tap. With many, all closed is easier to scan.' => 'ෆෝල්ඩර කිහිපයක් පමණක් ඇති විට, සියල්ල විවෘතව තැබීමෙන් එක් ක්ලික් කිරීමක් ඉතිරි වේ. බොහෝ ඒවා ඇති විට, සියල්ල වසා තැබීම බැලීමට පහසුයි.',
    'milliseconds (1000 = 1 second)' => 'මිලිතත්පර (1000 = තත්පර 1)',
    'px (0 = square corners)' => 'px (0 = හතරැස් කොන්)',
    'seconds' => 'තත්පර',

    // ---- Ad designer: look names and their one-line hints --------------
    'A boxed notice with a coloured edge.' => 'වර්ණවත් දාරයක් සහිත කොටු කළ දැනුම්දීමක්.',
    'A heading, a sentence and a button.' => 'ශීර්ෂයක්, වාක්‍යයක් සහ බොත්තමක්.',
    'A torn-edge look, for an event or a seminar.' => 'ඉරුණු දාර පෙනුමක්, අවස්ථාවක් හෝ සම්මන්ත්‍රණයක් සඳහා.',
    'Banner' => 'පටිය',
    'Centred, with a soft glow. For something big.' => 'මැදට, මෘදු දීප්තියක් සමඟ. ලොකු දෙයක් සඳහා.',
    'Forest' => 'වනාන්තර',
    'Ink' => 'තීන්ත',
    'Notice card' => 'දැනුම්දීම් කාඩ්පත',
    'One line across the page. Quietest option.' => 'පිටුව හරහා එක් පේළියක්. නිහඬම විකල්පය.',
    'Plain strip' => 'සරල පටිය',
    'Royal blue' => 'රාජකීය නිල්',
    'Side by side' => 'එක පැත්තකට',
    'Soft mint' => 'මෘදු මින්ට්',
    'Soft sky' => 'මෘදු අහස',
    'Spotlight' => 'කේන්ද්‍රගත',
    'Ticket' => 'ටිකට්පත',
    'Words on the left, the button on the right.' => 'වම් පැත්තේ වචන, දකුණු පැත්තේ බොත්තම.',

    // ---- Teacher's dashboard: progress screen and the two charts ------
    '1 paper marked' => 'ප්‍රශ්න පත්‍ර 1ක් පරීක්ෂා කර ඇත',
    '{n} papers marked' => 'ප්‍රශ්න පත්‍ර {n}ක් පරීක්ෂා කර ඇත',
    '1 student did not sit it' => 'සිසුන් 1 දෙනෙක් ලියා නැත',
    '{n} did not sit it' => 'සිසුන් {n} දෙනෙක් ලියා නැත',
    '{n} sat' => '{n} දෙනෙක් ලිව්වා',
    'of {n}' => '{n} න්',
    '35 to 49%' => '35 සිට 49% දක්වා',
    '50 to 74%' => '50 සිට 74% දක්වා',
    '75% and over' => '75% සහ ඊට වැඩි',
    'Under 35%' => '35% ට අඩු',
    'A quiz nobody sat is not a hard quiz -- it is one they never saw, and its average means nothing.' => 'කිසිවෙකු නොලියූ ප්‍රශ්නාවලියක් අමාරු ප්‍රශ්නාවලියක් නොවේ -- එය ඔවුන් කිසිදා නොදුටු එකකි, එහි සාමාන්‍යයෙන් කිසිම අදහසක් නැත.',
    'An average of 60 can be everyone at 60, or half at 95 and half at 25. Those are opposite problems, and the average hides both.' => '60 ක සාමාන්‍යයක් කියන්නේ හැමෝම 60 ගත්තා කියන එක වෙන්න පුළුවන්, නැත්නම් බාගයක් 95 ත් බාගයක් 25 ත් ගත්තා කියන එකත් වෙන්න පුළුවන්. ඒ දෙක විරුද්ධ ප්‍රශ්න දෙකක්, සාමාන්‍යයෙන් දෙකම සැඟවේ.',
    'Back to teaching' => 'ඉගැන්වීමට ආපසු',
    'Class progress' => 'පන්තියේ ප්‍රගතිය',
    'How they are doing' => 'ඔවුන් කොහොමද',
    'Mark the register' => 'ලේඛනය සලකුණු කරන්න',
    'Marks by grade -- the spread, not the average' => 'ශ්‍රේණිය අනුව ලකුණු -- සාමාන්‍යය නොව, විසිරීම',
    'Material & videos' => 'උපකරණ සහ වීඩියෝ',
    'Need attention' => 'අවධානය අවශ්‍යයි',
    'No grade set' => 'ශ්‍රේණියක් සකසා නැත',
    'No students are enrolled in this class yet.' => 'තවම මෙම පන්තියට සිසුන් ඇතුළත් කර නැත.',
    'None posted' => 'දමා නැත',
    'None yet' => 'තවම නැත',
    'Nothing on record yet' => 'තවම කිසිම වාර්තාවක් නැත',
    'Post to this class' => 'මෙම පන්තියට දමන්න',
    'Send a notice' => 'දැනුම්දීමක් යවන්න',
    'That class is not yours.' => 'එම පන්තිය ඔබගේ නොවේ.',
    'That class no longer exists.' => 'එම පන්තිය තවදුරටත් නොපවතී.',
    'This grade is split: the gap between the weakest and strongest paper is {n} marks.' => 'මෙම ශ්‍රේණිය දෙකඩ වී ඇත: දුර්වලම සහ හොඳම ප්‍රශ්න පත්‍රය අතර පරතරය ලකුණු {n} කි.',
    'Who actually sat each quiz' => 'එක් එක් ප්‍රශ්නාවලිය ඇත්තටම ලිව්වේ කවුද',
    'Worst first, so the students who need you are at the top. "Nothing on record yet" is listed first of all -- a child with no quiz, no attendance and nothing opened is not doing fine, they are invisible.' => 'දුර්වලම එක මුලින්, එවිට ඔබේ අවධානය ඕන සිසුන් උඩින්ම සිටී. "තවම කිසිම වාර්තාවක් නැත" කියන ඒවා සියල්ලටම පෙර පෙන්වයි -- ප්‍රශ්නාවලියක්, පැමිණීමක් හෝ විවෘත කළ උපකරණයක් නැති දරුවෙක් හොඳින් ඉන්නේ නැත, ඔවුන් නොපෙනී ගිහින්.',
    'average' => 'සාමාන්‍යය',
    'highest' => 'ඉහළම',

    // ---- Posting material: the four kinds, each its own screen --------
    'What are you posting?' => 'ඔබ දමන්නේ කුමක්ද?',
    'Lesson recording' => 'පාඩමේ පටිගත කිරීම',
    'The Zoom recording of a class you taught.' => 'ඔබ ඉගැන්වූ පන්තියක Zoom පටිගත කිරීම.',
    'Notes or a paper' => 'සටහන් හෝ ප්‍රශ්න පත්‍රයක්',
    'A PDF or a photo: tutes, notes, a past paper.' => 'PDF එකක් හෝ ඡායාරූපයක්: ටියුට්, සටහන්, පසුගිය ප්‍රශ්න පත්‍රයක්.',
    'Lab or lesson video' => 'විද්‍යාගාර හෝ පාඩම් වීඩියෝව',
    'An experiment you filmed, or any other video.' => 'ඔබ රූගත කළ පරීක්ෂණයක්, හෝ වෙනත් ඕනෑම වීඩියෝවක්.',
    'A link' => 'සබැඳියක්',
    'Anything already on the web that they should read or watch.' => 'ඔවුන් කියවිය හෝ බැලිය යුතු, දැනටමත් අන්තර්ජාලයේ ඇති ඕනෑම දෙයක්.',
    'Pick one of the four above to start.' => 'පටන් ගැනීමට ඉහත හතරෙන් එකක් තෝරන්න.',
    'Post a lesson recording' => 'පාඩමේ පටිගත කිරීමක් දමන්න',
    'Post notes or a paper' => 'සටහන් හෝ ප්‍රශ්න පත්‍රයක් දමන්න',
    'Post a lab or lesson video' => 'විද්‍යාගාර හෝ පාඩම් වීඩියෝවක් දමන්න',
    'Post a link' => 'සබැඳියක් දමන්න',
    'Post something else' => 'වෙනත් දෙයක් දමන්න',
    'Zoom share link' => 'Zoom බෙදාගැනීමේ සබැඳිය',
    'Copy the share link from Zoom and paste it here.' => 'Zoom එකෙන් බෙදාගැනීමේ සබැඳිය පිටපත් කර මෙහි අලවන්න.',
    'Choose the file' => 'ගොනුව තෝරන්න',
    'PDF, PNG or JPG, up to 20 MB.' => 'PDF, PNG හෝ JPG, උපරිම 20 MB.',
    'Video link' => 'වීඩියෝ සබැඳිය',
    'Upload the video to YouTube as "Unlisted", or to Google Drive, and paste the link here. Videos are not stored on the class website -- they are too big for it, and the upload would fail halfway.' => 'වීඩියෝව YouTube එකට "Unlisted" ලෙස, නැතහොත් Google Drive එකට උඩුගත කර, සබැඳිය මෙහි අලවන්න. වීඩියෝ පන්ති වෙබ් අඩවියේ ගබඩා නොවේ -- ඒවා ඊට විශාල වැඩියි, උඩුගත කිරීම අඩකදී නතර වේ.',
    'Check it opens for someone who is not signed in to your account.' => 'ඔබේ ගිණුමට පිවිස නැති කෙනෙකුට එය විවෘත වේද කියා පරීක්ෂා කරන්න.',
    'A link or a file -- one or the other. Zoom recordings and YouTube videos belong on a link; notes and past papers are better uploaded.' => 'සබැඳියක් හෝ ගොනුවක් -- එකක් පමණි. Zoom පටිගත කිරීම් සහ YouTube වීඩියෝ සබැඳියකට අයිතියි; සටහන් සහ පසුගිය ප්‍රශ්න පත්‍ර උඩුගත කිරීම හොඳයි.',
    'e.g. Chemical Reactions -- full lesson recording' => 'උදා: රසායනික ප්‍රතික්‍රියා -- සම්පූර්ණ පාඩමේ පටිගත කිරීම',
    'e.g. Acids and Bases -- tute 3' => 'උදා: අම්ල සහ භෂ්ම -- ටියුට් 3',
    'e.g. Testing for starch -- lab demonstration' => 'උදා: පිෂ්ඨය පරීක්ෂා කිරීම -- විද්‍යාගාර නිරූපණය',
    'e.g. The water cycle -- short explainer' => 'උදා: ජල චක්‍රය -- කෙටි පැහැදිලි කිරීමක්',

    // Quiz flow: the three steps, and what each quiz is waiting on.
    'Set the paper' => 'ප්‍රශ්න පත්‍රය සකසන්න',
    'Add the questions' => 'ප්‍රශ්න එකතු කිරීම',
    'Publish it' => 'ප්‍රකාශයට පත් කරන්න',
    'Until it is published the class cannot see it.' => 'ප්‍රකාශයට පත් කරන තුරු පන්තියට එය නොපෙනේ.',
    'Add questions' => 'ප්‍රශ්න එකතු කරන්න',
    'No questions yet -- the class cannot sit this.' => 'තවම ප්‍රශ්න නැත -- පන්තියට මෙයට පෙනී සිටිය නොහැක.',

    // Read-only views for roles that cannot manage classes or students.
    'View only' => 'බැලීම පමණි',
    'No classes have been set up for you yet. The office creates them.' => 'තවම ඔබ වෙනුවෙන් පන්ති සකස් කර නැත. ඒවා සකස් කරන්නේ කාර්යාලයයි.',
    'Click "Create Class" to schedule your first tuition course.' => 'ඔබේ පළමු පන්තිය සකස් කිරීමට "Create Class" ක්ලික් කරන්න.',
    'Try adjusting your filters.' => 'ඔබේ පෙරහන් වෙනස් කර බලන්න.',

    // Row links into a class from the class list.
    'Quizzes set for this class' => 'මෙම පන්තියට දී ඇති ප්‍රශ්න පත්‍ර',
    'Material posted to this class' => 'මෙම පන්තියට දමා ඇති ඉගෙනුම් ද්‍රව්‍ය',

    // Read-only views for roles the routes already refuse.
    'No branches have been registered yet.' => 'තවම ශාඛා ලියාපදිංචි කර නැත.',
    'No homework has been set for this class yet. The class teacher sets it.' => 'තවම මෙම පන්තියට ගෙදර වැඩ දී නැත. ඒවා දෙන්නේ පන්තියේ ගුරුතුමියයි.',
    'View only -- the office edits student records.' => 'බැලීම පමණි -- සිසු තොරතුරු වෙනස් කරන්නේ කාර්යාලයයි.',
];
